@property --mup-drop-ft { syntax: "<length>"; inherits: false; initial-value: 0px; }
@property --mup-drop-fb { syntax: "<length>"; inherits: false; initial-value: 0px; }

/* Re-theme with --mup-drop-bg, -ink, -accent and -danger. */
.mup-drop {
  --mup-drop-bg: oklch(0.985 0.008 95);
  --mup-drop-ink: oklch(0.25 0.025 155);
  --mup-drop-accent: oklch(0.52 0.12 155);
  --mup-drop-danger: oklch(0.56 0.19 27);

  --mup-drop-dim: color-mix(in oklch, var(--mup-drop-ink) 60%, var(--mup-drop-bg));
  --mup-drop-faint: color-mix(in oklch, var(--mup-drop-ink) 34%, var(--mup-drop-bg));
  --mup-drop-line: color-mix(in oklch, var(--mup-drop-ink) 11%, var(--mup-drop-bg));
  --mup-drop-raise: color-mix(in oklch, white 75%, var(--mup-drop-bg));
  --mup-drop-tone: var(--mup-drop-accent);
  --mup-drop-ease: cubic-bezier(.22, 1, .36, 1);
  --mup-drop-in: cubic-bezier(.5, 0, .75, 0);
  --mup-drop-spring: linear(0, 0.034 2.3%, 0.13 4.7%, 0.484 11.6%, 0.656 15.5%, 0.786 19.5%, 0.883 23.6%, 0.951 27.9%, 1.006 33.3%, 1.03 38.5%, 1.037 44.2%, 1.025 54.1%, 1.008 66.8%, 1);

  container-type: inline-size;
  position: relative;
  display: grid;
  grid-template-areas: "head" "zone" "list" "foot";
  grid-template-columns: minmax(0, 1fr);
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  padding: 14px;
  border-radius: 18px;
  background: var(--mup-drop-bg);
  color: var(--mup-drop-ink);
  box-shadow: 0 1px 0 color-mix(in oklch, white 60%, transparent) inset, 0 0 0 1px var(--mup-drop-line), 0 18px 40px -28px color-mix(in oklch, var(--mup-drop-ink) 60%, transparent);
  font: 400 13px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-align: left;
  accent-color: var(--mup-drop-accent);
}
@supports not (transition-timing-function: linear(0, 1)) {
  .mup-drop { --mup-drop-spring: cubic-bezier(.3, 1.35, .5, 1); }
}
.mup-drop[data-state="reject"] { --mup-drop-tone: var(--mup-drop-danger); }
:where(.mup-drop) *, :where(.mup-drop) *::before, :where(.mup-drop) *::after { box-sizing: border-box; }
:where(.mup-drop) :is(p, h3, ul, li) { margin: 0; padding: 0; list-style: none; }
:where(.mup-drop) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
:where(.mup-drop) :focus-visible { outline: 2px solid var(--mup-drop-accent); outline-offset: 2px; }
.mup-drop svg { fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }

.mup-drop__head {
  grid-area: head; display: flex; align-items: end; justify-content: space-between; gap: 10px; margin-bottom: 12px;
  & div { min-width: 0; }
  & h3 { font-size: clamp(15px, 5cqi, 18px); font-weight: 700; letter-spacing: -.015em; line-height: 1.15; text-wrap: balance; }
}
.mup-drop__eyebrow {
  font-size: 10.5px; font-weight: 650; letter-spacing: .1em; text-transform: uppercase; color: var(--mup-drop-dim);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; margin-bottom: 3px;
}
.mup-drop__count {
  display: flex; align-items: baseline; gap: 3px; flex: none;
  font: 600 12px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; color: var(--mup-drop-dim);
  & b { font-size: 15px; color: var(--mup-drop-ink); }
}
.mup-drop[data-full] .mup-drop__count b { color: var(--mup-drop-accent); }

/* ---------- the zone ---------- */
.mup-drop__zone {
  grid-area: zone; position: relative; isolation: isolate;
  display: grid; grid-template-areas: "art" "copy"; justify-items: center; gap: 10px;
  padding: clamp(18px, 8cqi, 30px) 16px clamp(16px, 6.5cqi, 24px);
  border-radius: 14px; text-align: center;
  background: var(--mup-drop-raise);
  transition: background-color .3s, scale .5s var(--mup-drop-spring), padding .45s var(--mup-drop-ease), gap .45s var(--mup-drop-ease);
  &::before {
    content: ""; position: absolute; inset: 0; z-index: -1; border-radius: inherit; pointer-events: none;
    background: radial-gradient(circle at var(--mup-drop-x, 50%) var(--mup-drop-y, 50%), color-mix(in oklch, var(--mup-drop-tone) 22%, transparent), transparent 62%);
    opacity: 0; transition: opacity .3s;
  }
  &:hover .mup-drop__ring rect { stroke: var(--mup-drop-dim); }
  &:hover .mup-drop__arrow { translate: 0 1.5px; }
  &:focus-visible { outline-offset: 3px; }
}
.mup-drop__ring {
  position: absolute; inset: 1px; width: calc(100% - 2px); height: calc(100% - 2px); overflow: visible; pointer-events: none;
  & rect { fill: none; stroke: var(--mup-drop-faint); stroke-width: 1.5; stroke-dasharray: 7 6; transition: stroke .25s, stroke-width .25s; }
}
.mup-drop__art { grid-area: art; position: relative; display: grid; place-items: center; width: 52px; height: 46px; }
.mup-drop__tray {
  width: 40px; height: 40px; color: var(--mup-drop-accent); stroke-width: 1.5;
  transition: color .25s, translate .45s var(--mup-drop-spring);
}
.mup-drop__arrow { transition: translate .45s var(--mup-drop-spring), opacity .2s; }
.mup-drop__copy { grid-area: copy; display: grid; gap: 3px; min-width: 0; }
.mup-drop__title { font-size: clamp(13.5px, 4.3cqi, 15px); font-weight: 650; letter-spacing: -.01em; text-wrap: balance; }
.mup-drop__title u { text-decoration-thickness: 1.5px; text-underline-offset: 3px; text-decoration-color: color-mix(in oklch, var(--mup-drop-accent) 55%, transparent); color: var(--mup-drop-accent); }
.mup-drop__sub { font-size: 12px; color: var(--mup-drop-dim); text-wrap: pretty; transition: color .2s; }

/* ghost cards: a preview of what is about to land, read from DataTransfer.items */
.mup-drop__ghosts { position: absolute; inset: 0; pointer-events: none; }
.mup-drop__ghosts i {
  position: absolute; left: 50%; top: 50%; width: 20px; height: 26px; margin: -16px 0 0 -10px; border-radius: 3px;
  clip-path: polygon(0 0, 68% 0, 100% 26%, 100% 100%, 0 100%);
  background: linear-gradient(transparent 62%, var(--mup-drop-gc, var(--mup-drop-accent)) 0) , var(--mup-drop-bg);
  box-shadow: inset 0 0 0 1.5px var(--mup-drop-gc, var(--mup-drop-accent));
  opacity: 0; translate: 0 12px; scale: .5; rotate: 0deg;
  transition: opacity .2s, translate .5s var(--mup-drop-spring), scale .5s var(--mup-drop-spring), rotate .5s var(--mup-drop-spring);
}
.mup-drop__ghosts i[data-k="img"] { --mup-drop-gc: oklch(0.6 0.11 200); }
.mup-drop__ghosts i[data-k="pdf"] { --mup-drop-gc: oklch(0.6 0.16 30); }
.mup-drop__ghosts i[data-k="bad"] { --mup-drop-gc: var(--mup-drop-danger); }
.mup-drop__ghosts i[data-k="any"] { --mup-drop-gc: var(--mup-drop-faint); }

.mup-drop:is([data-state="over"], [data-state="reject"]) {
  & .mup-drop__zone { background: color-mix(in oklch, var(--mup-drop-tone) 7%, var(--mup-drop-raise)); scale: 1.015; }
  & .mup-drop__zone::before { opacity: 1; }
  & .mup-drop__ring rect { stroke: var(--mup-drop-tone); stroke-width: 2; animation: mup-drop-march .55s linear infinite; }
  & .mup-drop__tray { color: var(--mup-drop-tone); translate: 0 8px; }
  & .mup-drop__arrow { opacity: 0; translate: 0 4px; }
  & .mup-drop__sub { color: color-mix(in oklch, var(--mup-drop-tone) 80%, var(--mup-drop-ink)); }
  & .mup-drop__ghosts i { transition-delay: calc(var(--mup-drop-gi, 0) * 45ms); }
}
.mup-drop[data-state="reject"] .mup-drop__ring rect { animation: none; stroke-dasharray: 3 5; }
.mup-drop:is([data-state="over"], [data-state="reject"]) .mup-drop__ghosts {
  & i[data-on] { opacity: 1; scale: 1; }
  & i[data-g="1"] { translate: 0 -14px; }
  & i[data-g="0"] { translate: -15px -7px; rotate: -12deg; }
  & i[data-g="2"] { translate: 15px -7px; rotate: 12deg; }
}
.mup-drop[data-state="reject"] .mup-drop__ghosts { animation: mup-drop-shake .42s var(--mup-drop-ease) .15s; }
.mup-drop[data-shake] .mup-drop__zone { animation: mup-drop-shake .42s var(--mup-drop-ease); }
@keyframes mup-drop-march { to { stroke-dashoffset: -13; } }
@keyframes mup-drop-shake { 20% { translate: -5px 0; } 45% { translate: 4px 0; } 70% { translate: -2px 0; } }

/* compact zone once something is attached: the list becomes the subject */
.mup-drop:has(.mup-drop__file) .mup-drop__zone {
  grid-template-areas: "art copy"; grid-template-columns: auto minmax(0, 1fr); justify-items: start; text-align: left;
  gap: 12px; padding: 12px 14px;
  & .mup-drop__art { width: 36px; height: 34px; }
  & .mup-drop__tray { width: 28px; height: 28px; }
  & .mup-drop__title { font-size: 13.5px; }
}
.mup-drop[data-full] .mup-drop__zone { cursor: not-allowed; }
.mup-drop[data-full] .mup-drop__zone .mup-drop__tray { color: var(--mup-drop-faint); }
.mup-drop[data-full] .mup-drop__title u { color: inherit; text-decoration: none; }

/* ---------- file rows ---------- */
.mup-drop__list {
  grid-area: list; display: grid; gap: 6px; max-height: 232px; overflow-y: auto; overscroll-behavior: contain;
  scrollbar-width: thin; margin-inline: -4px; padding: 0 4px;
  &:not(:empty) { margin-top: 10px; padding-block: 2px; }
}
@supports (animation-timeline: scroll()) {
  .mup-drop__list {
    mask-image: linear-gradient(transparent, #000 var(--mup-drop-ft), #000 calc(100% - var(--mup-drop-fb)), transparent);
    animation: mup-drop-fade linear both; animation-timeline: scroll(self);
  }
  @keyframes mup-drop-fade {
    0% { --mup-drop-ft: 0px; --mup-drop-fb: 18px; }
    10% { --mup-drop-ft: 18px; }
    90% { --mup-drop-fb: 18px; }
    100% { --mup-drop-ft: 18px; --mup-drop-fb: 0px; }
  }
}
.mup-drop__file {
  position: relative; overflow: hidden;
  display: grid; grid-template-areas: "doc name act" "doc info act"; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center;
  column-gap: 10px; padding: 8px 6px 9px 8px; border-radius: 11px;
  background: var(--mup-drop-raise); box-shadow: inset 0 0 0 1px var(--mup-drop-line);
  transition: opacity .35s var(--mup-drop-ease), translate .5s var(--mup-drop-spring), background-color .4s;
  transition-delay: calc(var(--i, 0) * 70ms), calc(var(--i, 0) * 70ms), 0s;
}
@starting-style {
  .mup-drop__file { opacity: 0; translate: 0 10px; }
}
.mup-drop__doc {
  grid-area: doc; position: relative; display: grid; place-items: center; width: 32px; height: 36px;
  color: var(--mup-drop-kc, var(--mup-drop-accent));
  & > svg:first-child { width: 30px; height: 34px; stroke-width: 1.4; }
  & b {
    position: absolute; left: 50%; bottom: 6px; translate: -50% 0; padding: 1px 3px; border-radius: 3px;
    background: var(--mup-drop-kc, var(--mup-drop-accent)); color: var(--mup-drop-bg);
    font: 750 7.5px/1.2 ui-monospace, Menlo, monospace; letter-spacing: .04em;
  }
}
.mup-drop__file[data-kind="pdf"] { --mup-drop-kc: oklch(0.56 0.16 30); }
.mup-drop__file[data-kind="png"], .mup-drop__file[data-kind="jpg"] { --mup-drop-kc: oklch(0.52 0.1 205); }
.mup-drop__file[data-kind="bad"] { --mup-drop-kc: var(--mup-drop-faint); }
.mup-drop__name { grid-area: name; font-weight: 600; font-size: 13px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mup-drop__info {
  grid-area: info; font-size: 11.5px; color: var(--mup-drop-dim); font-variant-numeric: tabular-nums;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.mup-drop__bar {
  position: absolute; left: 0; right: 0; bottom: 0; height: 2.5px; background: var(--mup-drop-line);
  transition: opacity .5s .4s;
  & i { display: block; height: 100%; background: var(--mup-drop-accent); transform-origin: left; transform: scaleX(var(--mup-drop-p, 0)); }
}
.mup-drop__x {
  grid-area: act; display: grid; place-items: center; width: 30px; height: 30px; border-radius: 8px; color: var(--mup-drop-dim);
  transition: background-color .15s, color .15s;
  & svg { width: 16px; height: 16px; }
  &:hover { background: color-mix(in oklch, var(--mup-drop-ink) 7%, transparent); color: var(--mup-drop-ink); }
}
.mup-drop__tick {
  position: absolute; right: -5px; top: -1px; width: 15px; height: 15px; padding: 2px; border-radius: 50%;
  background: var(--mup-drop-accent); color: var(--mup-drop-bg); stroke-width: 3.2;
  scale: 0; transition: scale .45s var(--mup-drop-spring);
  & path { stroke-dasharray: 16; stroke-dashoffset: 16; transition: stroke-dashoffset .35s var(--mup-drop-ease) .15s; }
}
.mup-drop__file[data-status="done"] {
  background: color-mix(in oklch, var(--mup-drop-accent) 6%, var(--mup-drop-raise));
  & .mup-drop__bar { opacity: 0; }
  & .mup-drop__tick { scale: 1; }
  & .mup-drop__tick path { stroke-dashoffset: 0; }
}
.mup-drop__file[data-status="err"] {
  background: color-mix(in oklch, var(--mup-drop-danger) 6%, var(--mup-drop-raise));
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--mup-drop-danger) 26%, transparent);
  & .mup-drop__name { color: var(--mup-drop-dim); text-decoration: line-through; text-decoration-color: color-mix(in oklch, var(--mup-drop-danger) 50%, transparent); }
  & .mup-drop__info { color: var(--mup-drop-danger); font-weight: 550; }
  & .mup-drop__bar { display: none; }
}

/* ---------- footer ---------- */
.mup-drop__foot {
  grid-area: foot; display: flex; align-items: center; gap: 12px; margin-top: 12px; padding-top: 11px;
  border-top: 1px solid var(--mup-drop-line);
}
.mup-drop__status { flex: 1; min-width: 0; font-size: 12px; color: var(--mup-drop-dim); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mup-drop__status b { color: var(--mup-drop-ink); font-weight: 650; }
.mup-drop__link {
  flex: none; padding: 5px 9px; margin: -5px -4px; border-radius: 7px; font-size: 12px; font-weight: 600; color: var(--mup-drop-accent);
  transition: background-color .15s;
  &:hover { background: color-mix(in oklch, var(--mup-drop-accent) 10%, transparent); }
  &:disabled { color: var(--mup-drop-faint); cursor: default; background: none; }
  &[hidden] { display: none; }
}
.mup-drop__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

@container (min-width: 380px) {
  .mup-drop:not(:has(.mup-drop__file)) .mup-drop__zone { grid-template-areas: "art copy"; grid-template-columns: auto auto; justify-content: center; text-align: left; gap: 16px; }
}
@container (max-width: 300px) {
  .mup-drop__eyebrow { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .mup-drop__zone, .mup-drop__tray, .mup-drop__arrow, .mup-drop__ghosts i, .mup-drop__file, .mup-drop__tick, .mup-drop__tick path {
    transition-duration: .01s; transition-delay: 0s;
  }
  .mup-drop:is([data-state="over"], [data-state="reject"]) .mup-drop__zone { scale: 1; }
  .mup-drop:is([data-state="over"], [data-state="reject"]) .mup-drop__ring rect { animation: none; stroke-dasharray: none; }
  .mup-drop[data-state="reject"] .mup-drop__ghosts, .mup-drop[data-shake] .mup-drop__zone { animation: none; }
  .mup-drop:is([data-state="over"], [data-state="reject"]) .mup-drop__tray { translate: 0 0; }
}

