const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const later = (ms, fn) => setTimeout(() => { if (root.isConnected) fn(); }, ms);
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const EASE = 'cubic-bezier(.22,1,.36,1)';

const LIMIT = 6, MAX = 25e6;
const MIME = { 'application/pdf': 'pdf', 'image/png': 'png', 'image/jpeg': 'jpg' };
const EXT = { pdf: 'pdf', png: 'png', jpg: 'jpg', jpeg: 'jpg' };
const PLURAL = {
  'application/zip': 'ZIP archive', 'application/x-zip-compressed': 'ZIP archive', 'image/gif': 'GIF',
  'image/heic': 'HEIC photo', 'image/webp': 'WebP image', 'image/svg+xml': 'SVG file', 'text/plain': 'text file',
  'text/csv': 'CSV file', 'application/json': 'JSON file'
};
const SAMPLES = [
  { name: 'larkspur-moodboard.pdf', size: 8.4e6, type: 'application/pdf' },
  { name: 'hero-crop-02.png', size: 3.1e6, type: 'image/png' },
  { name: 'type-specimen.jpg', size: 2.7e6, type: 'image/jpeg' },
  { name: 'fonts-v2.zip', size: 12.8e6, type: 'application/zip' }
];

const zone = $('.mup-drop__zone'), input = $('.mup-drop__input'), list = $('.mup-drop__list'), live = $('.mup-drop__sr');
const title = $('[data-title]'), sub = $('[data-sub]'), countEl = $('[data-count]'), statusEl = $('[data-status]');
const sampleBtn = $('[data-act="sample"]'), clearBtn = $('[data-act="clear"]');
const ghosts = $$('.mup-drop__ghosts i');
const IDLE_TITLE = title.innerHTML, IDLE_SUB = sub.textContent;

let files = [], uid = 0, depth = 0, raf = 0, last = 0, onscreen = true, demo = false;

const say = (m) => { live.textContent = ''; later(40, () => { live.textContent = m; }); };
const fmt = (b) => b < 1e6 ? Math.max(1, Math.round(b / 1e3)) + ' KB' : (b / 1e6).toFixed(1) + ' MB';
const extOf = (n) => (n.includes('.') ? n.split('.').pop() : '').toLowerCase();
const kindOf = (name, type) => MIME[type] || (!type || type === 'application/octet-stream' ? EXT[extOf(name)] : null) || null;
const noun = (type, name) => {
  if (PLURAL[type]) return PLURAL[type];
  if (/^video\//.test(type)) return 'video';
  if (/^audio\//.test(type)) return 'audio file';
  const e = extOf(name);
  return e ? e.toUpperCase() + ' file' : 'file of this type';
};
const refuse = (type, name) => {
  const w = noun(type, name);
  return w === 'file of this type' ? 'This file type isn’t accepted' : w.replace(/^./, (c) => c.toUpperCase()) + 's aren’t accepted';
};
const plural = (n, w) => n + ' ' + w + (n === 1 ? '' : 's');
const live$ = () => files.filter((f) => f.state !== 'err');
const hash = (s) => [...s].reduce((h, c) => (h * 31 + c.charCodeAt(0)) >>> 0, 7);

/* ---------- rows ---------- */
const DOC = '<svg viewBox="0 0 24 28"><path d="M5 2.75h9.25l4.75 4.75v17.75H5z"/><path d="M14.25 2.75V7.5H19"/></svg>';
const X = '<svg viewBox="0 0 24 24"><path d="M7 7l10 10M17 7 7 17"/></svg>';
const TICK = '<svg class="mup-drop__tick" viewBox="0 0 24 24"><path d="m6 12.5 4 4 8-9"/></svg>';

function makeRow(f, i) {
  const li = document.createElement('li');
  li.className = 'mup-drop__file';
  li.dataset.kind = f.kind || 'bad';
  li.dataset.status = f.state;
  li.style.setProperty('--i', i);
  const tag = (f.kind || extOf(f.name) || '?').slice(0, 4).toUpperCase();
  li.innerHTML =
    '<span class="mup-drop__doc" aria-hidden="true">' + DOC + '<b>' + esc(tag) + '</b>' + TICK + '</span>' +
    '<span class="mup-drop__name" title="' + esc(f.name) + '">' + esc(f.name) + '</span>' +
    '<span class="mup-drop__info"></span>' +
    (f.state === 'err' ? '' : '<span class="mup-drop__bar" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0" aria-label="Uploading ' + esc(f.name) + '"><i></i></span>') +
    '<button type="button" class="mup-drop__x">' + X + '</button>';
  f.el = li; f.info = $('.mup-drop__info', li); f.bar = $('.mup-drop__bar', li); f.btn = $('.mup-drop__x', li);
  later(600 + i * 70, () => li.style.removeProperty('--i'));
  paintRow(f);
  return li;
}
function paintRow(f) {
  f.el.dataset.status = f.state;
  if (f.state === 'err') {
    f.info.textContent = f.reason;
    f.btn.setAttribute('aria-label', 'Dismiss ' + f.name + ', ' + f.reason);
    return;
  }
  const pct = Math.floor((f.sent / f.size) * 100);
  f.el.style.setProperty('--mup-drop-p', (f.sent / f.size).toFixed(4));
  if (pct === f.pct && f.state === f.shown) return;
  f.pct = pct; f.shown = f.state;
  f.bar.setAttribute('aria-valuenow', pct);
  if (f.state === 'done') {
    f.info.textContent = fmt(f.size) + ' · Uploaded';
    f.btn.setAttribute('aria-label', 'Remove ' + f.name);
    f.bar.removeAttribute('aria-label');
    f.bar.setAttribute('aria-hidden', 'true');
  } else {
    f.info.textContent = fmt(f.sent) + ' of ' + fmt(f.size) + ' · ' + pct + '%';
    f.btn.setAttribute('aria-label', 'Cancel upload of ' + f.name);
  }
}

/* ---------- summary ---------- */
function sync() {
  const ok = live$(), up = ok.filter((f) => f.state === 'up');
  const full = ok.length >= LIMIT;
  countEl.textContent = ok.length;
  root.toggleAttribute('data-full', full);
  zone.setAttribute('aria-disabled', String(full));
  if (root.dataset.state === 'idle') {
    if (full) { title.textContent = 'Limit reached'; sub.textContent = 'Remove a file to attach another'; }
    else if (title.innerHTML !== IDLE_TITLE) { title.innerHTML = IDLE_TITLE; sub.textContent = IDLE_SUB; }
  }
  const bytes = ok.reduce((a, f) => a + f.size, 0);
  if (!files.length) statusEl.textContent = 'Nothing attached yet';
  else if (up.length) {
    const sent = ok.reduce((a, f) => a + f.sent, 0);
    statusEl.innerHTML = 'Uploading <b>' + up.length + '</b> of ' + ok.length + ' · <b>' + Math.floor((sent / bytes) * 100) + '%</b>';
  } else if (ok.length) statusEl.innerHTML = '<b>' + plural(ok.length, 'file') + '</b> · ' + fmt(bytes) + ' uploaded';
  else statusEl.textContent = 'No files accepted';
  clearBtn.hidden = !files.length;
  sampleBtn.hidden = !!files.length;
  sampleBtn.disabled = demo;
}

/* ---------- upload simulation ---------- */
function tick(t) {
  if (!root.isConnected) { io.disconnect(); return; }
  raf = 0;
  const dt = Math.min(0.1, (t - last) / 1000);
  last = t;
  for (const f of files) {
    if (f.state !== 'up') continue;
    const wobble = 0.82 + 0.36 * Math.abs(Math.sin(t / 420 + f.id));
    f.sent = Math.min(f.size, f.sent + f.speed * wobble * dt);
    if (f.sent >= f.size) {
      f.state = 'done';
      say(f.name + ' uploaded.');
    }
    paintRow(f);
  }
  sync();
  if (onscreen && files.some((f) => f.state === 'up')) raf = requestAnimationFrame(tick);
}
function kick() {
  if (raf || !onscreen || !files.some((f) => f.state === 'up')) return;
  last = performance.now();
  raf = requestAnimationFrame(tick);
}

function add(items) {
  let room = LIMIT - live$().length, accepted = 0, i = 0;
  const rejected = [];
  for (const it of items) {
    const kind = kindOf(it.name, it.type || '');
    let reason = '';
    if (!kind) reason = refuse(it.type || '', it.name);
    else if (it.size > MAX) reason = fmt(it.size) + ' · over the 25 MB limit';
    else if (accepted >= room) reason = 'Over the 6-file limit';
    const f = { id: ++uid, name: it.name, size: it.size, kind, sent: 0, state: reason ? 'err' : 'up', reason, speed: 2.4e6 + (hash(it.name) % 8) * 0.22e6 };
    if (!reason) accepted++; else rejected.push(f);
    files.push(f);
    list.append(makeRow(f, i++));
  }
  sync();
  kick();
  let msg = accepted ? plural(accepted, 'file') + ' added.' : 'No files added.';
  if (rejected.length) msg += ' ' + rejected.map((f) => f.name + ': ' + f.reason).join('. ') + '.';
  say(msg);
}

function removeFile(f, refocus) {
  const k = files.indexOf(f);
  if (k < 0) return;
  files.splice(k, 1);
  const el = f.el, sibs = [...list.children].filter((x) => x !== el);
  const done = () => {
    const before = sibs.map((x) => x.getBoundingClientRect().top);
    el.remove();
    sync();
    if (!RM.matches) sibs.forEach((x, j) => {
      const dy = before[j] - x.getBoundingClientRect().top;
      if (dy) x.animate([{ transform: 'translateY(' + dy + 'px)' }, { transform: 'none' }], { duration: 420, easing: EASE });
    });
    if (refocus) {
      const next = files[Math.min(k, files.length - 1)];
      (next ? next.btn : zone).focus();
    }
  };
  if (RM.matches) { done(); return; }
  el.style.pointerEvents = 'none';
  el.animate([{ opacity: 1, transform: 'none' }, { opacity: 0, transform: 'translateX(14px) scale(.97)' }], { duration: 190, easing: 'cubic-bezier(.5,0,.75,0)', fill: 'forwards' }).onfinish = done;
}

/* ---------- drag preview, from DataTransfer.items before anything is dropped ---------- */
const hasFiles = (e) => !!e.dataTransfer && [...e.dataTransfer.types].includes('Files');
function preview(entries) {
  const n = entries.length, room = LIMIT - live$().length;
  const kinds = entries.map((t) => (t ? (MIME[t] ? (t === 'application/pdf' ? 'pdf' : 'img') : 'bad') : 'any'));
  const bad = kinds.filter((k) => k === 'bad').length, good = n - bad;
  let state = 'over';
  if (room <= 0) { state = 'reject'; title.textContent = 'Limit reached'; sub.textContent = 'Remove a file before adding more'; }
  else if (!good) {
    state = 'reject';
    title.textContent = refuse(entries.find((t) => t && !MIME[t]) || '', '');
    sub.textContent = 'Only PDF, PNG and JPG';
  } else {
    title.textContent = 'Release to add ' + plural(Math.min(good, room), 'file');
    if (bad) sub.textContent = plural(bad, 'file') + ' of the wrong type will be skipped';
    else if (good > room) sub.textContent = 'Only ' + room + ' more fit · 6 max';
    else sub.textContent = 'PDF, PNG or JPG · up to 25 MB each';
  }
  root.dataset.state = state;
  root.dataset.n = Math.min(n, 3);
  const slots = n === 1 ? [1] : n === 2 ? [0, 2] : [0, 1, 2];
  ghosts.forEach((g, j) => {
    const at = slots.indexOf(j);
    g.toggleAttribute('data-on', at >= 0);
    g.dataset.k = at >= 0 ? kinds[Math.min(at, n - 1)] : '';
  });
}
function idle() {
  root.dataset.state = 'idle';
  root.dataset.n = 0;
  ghosts.forEach((g) => g.removeAttribute('data-on'));
  title.innerHTML = IDLE_TITLE; sub.textContent = IDLE_SUB;
  sync();
}
function spot(e) {
  const r = zone.getBoundingClientRect();
  zone.style.setProperty('--mup-drop-x', (((e.clientX - r.left) / r.width) * 100).toFixed(1) + '%');
  zone.style.setProperty('--mup-drop-y', (((e.clientY - r.top) / r.height) * 100).toFixed(1) + '%');
}
function shake() {
  root.removeAttribute('data-shake');
  void root.offsetWidth;
  root.setAttribute('data-shake', '');
  later(450, () => root.removeAttribute('data-shake'));
}

root.addEventListener('dragenter', (e) => {
  if (!hasFiles(e) || demo) return;
  e.preventDefault();
  if (++depth === 1) preview([...e.dataTransfer.items].filter((it) => it.kind === 'file').map((it) => it.type));
});
root.addEventListener('dragover', (e) => {
  if (!hasFiles(e) || demo) return;
  e.preventDefault();
  e.dataTransfer.dropEffect = root.dataset.state === 'reject' ? 'none' : 'copy';
  spot(e);
});
root.addEventListener('dragleave', (e) => {
  if (!hasFiles(e) || demo) return;
  depth = Math.max(0, depth - 1);
  if (!depth) idle();
});
root.addEventListener('drop', (e) => {
  if (!hasFiles(e) || demo) return;
  e.preventDefault();
  depth = 0;
  const rejected = root.dataset.state === 'reject';
  const dropped = [...e.dataTransfer.files];
  idle();
  if (rejected) shake();
  if (live$().length >= LIMIT) { say('Limit reached. Nothing was added.'); return; }
  add(dropped);
});

/* ---------- click, keyboard ---------- */
zone.addEventListener('click', () => {
  if (demo) return;
  if (live$().length >= LIMIT) { shake(); say('Limit reached. Remove a file to attach another.'); return; }
  input.click();
});
input.addEventListener('change', () => {
  if (input.files.length) add([...input.files]);
  input.value = '';
  zone.focus();
});
list.addEventListener('click', (e) => {
  const b = e.target.closest('.mup-drop__x');
  if (!b) return;
  const f = files.find((x) => x.btn === b);
  if (!f) return;
  const verb = f.state === 'up' ? 'Upload cancelled' : f.state === 'err' ? 'Dismissed' : 'Removed';
  removeFile(f, e.detail === 0);
  say(verb + ': ' + f.name + '.');
});
list.addEventListener('keydown', (e) => {
  const btns = files.map((f) => f.btn);
  const k = btns.indexOf(document.activeElement);
  if (k < 0) return;
  if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
    e.preventDefault();
    const n = btns[k + (e.key === 'ArrowDown' ? 1 : -1)];
    if (n) n.focus(); else if (e.key === 'ArrowUp') zone.focus();
  } else if (e.key === 'Home' || e.key === 'End') {
    e.preventDefault();
    btns[e.key === 'Home' ? 0 : btns.length - 1].focus();
  } else if (e.key === 'Delete' || e.key === 'Backspace') {
    e.preventDefault();
    btns[k].click();
  }
});
zone.addEventListener('keydown', (e) => {
  if (e.key === 'ArrowDown' && files.length) { e.preventDefault(); files[0].btn.focus(); }
});
clearBtn.addEventListener('click', () => {
  const n = files.length;
  files = [];
  list.replaceChildren();
  sync();
  sampleBtn.focus();
  say(plural(n, 'file') + ' cleared.');
});

/* sample files play the same drag states a real drop would, then land */
sampleBtn.addEventListener('click', () => {
  if (demo) return;
  demo = true;
  sync();
  const r = zone.getBoundingClientRect();
  spot({ clientX: r.left + r.width * 0.5, clientY: r.top + r.height * 0.35 });
  preview(SAMPLES.map((s) => s.type));
  say(title.textContent + '. ' + sub.textContent + '.');
  later(RM.matches ? 500 : 1050, () => {
    idle();
    demo = false;
    add(SAMPLES);
    later(60, () => { const f = files[0]; if (f && document.activeElement === sampleBtn) f.btn.focus(); });
  });
});

const io = new IntersectionObserver((es) => {
  if (!root.isConnected) { io.disconnect(); return; }
  onscreen = es[es.length - 1].isIntersecting;
  if (onscreen) kick();
});
io.observe(root);
sync();

css:
@property --mup-queue-n {
  syntax: "<integer>";
  inherits: true;
  initial-value: 0;
}
@property --mup-queue-ft { syntax: "<length>"; inherits: false; initial-value: 0px; }
@property --mup-queue-fb { syntax: "<length>"; inherits: false; initial-value: 0px; }

/* Re-theme with --mup-queue-bg, -fg, -accent and -fail. */
.mup-queue {
  --mup-queue-bg: oklch(0.205 0.006 260);
  --mup-queue-fg: oklch(0.95 0.005 260);
  --mup-queue-accent: oklch(0.87 0.18 128);
  --mup-queue-fail: oklch(0.7 0.17 28);

  --mup-queue-dim: color-mix(in oklch, var(--mup-queue-fg) 58%, var(--mup-queue-bg));
  --mup-queue-faint: color-mix(in oklch, var(--mup-queue-fg) 34%, var(--mup-queue-bg));
  --mup-queue-line: color-mix(in oklch, var(--mup-queue-fg) 10%, transparent);
  --mup-queue-raise: color-mix(in oklch, var(--mup-queue-fg) 5%, var(--mup-queue-bg));
  --mup-queue-well: color-mix(in oklch, black 28%, var(--mup-queue-bg));
  --mup-queue-on: color-mix(in oklch, black 78%, var(--mup-queue-accent));
  --mup-queue-ease: cubic-bezier(.22, 1, .36, 1);
  --mup-queue-spring: linear(0, 0.034 2.3%, 0.13 4.7%, 0.484 11.6%, 0.656 15.5%, 0.786 19.5%, 0.883 23.6%, 0.951 27.9%, 1.006 33.3%, 1.03 38.5%, 1.037 44.2%, 1.025 54.1%, 1.008 66.8%, 1);

  container-type: inline-size;
  position: relative;
  display: grid;
  grid-template-areas: "head" "bar" "stats" "tools" "list";
  grid-template-columns: minmax(0, 1fr);
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  padding: 14px 14px 10px;
  border-radius: 18px;
  background: var(--mup-queue-bg);
  color: var(--mup-queue-fg);
  box-shadow: inset 0 0 0 1px var(--mup-queue-line), inset 0 1px 0 color-mix(in oklch, var(--mup-queue-fg) 6%, transparent);
  font: 400 13px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-align: left;
}
@supports not (transition-timing-function: linear(0, 1)) {
  .mup-queue { --mup-queue-spring: cubic-bezier(.3, 1.35, .5, 1); }
}
:where(.mup-queue) *, :where(.mup-queue) *::before, :where(.mup-queue) *::after { box-sizing: border-box; }
:where(.mup-queue) :is(p, h3, ul, li) { margin: 0; padding: 0; list-style: none; }
:where(.mup-queue) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
:where(.mup-queue) :focus-visible { outline: 2px solid var(--mup-queue-accent); outline-offset: 2px; }
.mup-queue svg { fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; flex: none; }

.mup-queue__head { grid-area: head; display: flex; align-items: end; justify-content: space-between; gap: 12px; }
.mup-queue__titles { min-width: 0; }
.mup-queue__eyebrow {
  font-size: 10.5px; font-weight: 650; letter-spacing: .11em; text-transform: uppercase; color: var(--mup-queue-dim);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; margin-bottom: 3px;
}
.mup-queue__head h3 { font-size: clamp(15px, 5cqi, 18px); font-weight: 700; letter-spacing: -.015em; line-height: 1.15; text-wrap: balance; }
.mup-queue__pct {
  display: flex; align-items: baseline; flex: none; line-height: .9; color: var(--mup-queue-fg);
  font: 680 clamp(26px, 10cqi, 36px)/.9 ui-monospace, Menlo, monospace; letter-spacing: -.04em; font-variant-numeric: tabular-nums;
  & b { font-weight: inherit; transition: --mup-queue-n .6s var(--mup-queue-ease); counter-reset: mup-queue-p var(--mup-queue-n); }
  & b::before { content: counter(mup-queue-p); }
  & span { font-size: .48em; margin-left: 2px; color: var(--mup-queue-dim); letter-spacing: 0; }
}
.mup-queue[data-state="done"] .mup-queue__pct { color: var(--mup-queue-accent); }

/* ---------- the bar is the queue: one segment per file, grown by its bytes ---------- */
.mup-queue__bar {
  grid-area: bar; display: flex; gap: 2px; height: 10px; margin-top: 12px;
  & i {
    position: relative; flex: var(--mup-queue-w, 1) 1 0; min-width: 3px; overflow: hidden; border-radius: 2px;
    background: color-mix(in oklch, var(--mup-queue-fg) 11%, transparent);
    transition: flex-grow .5s var(--mup-queue-ease), background-color .25s, translate .3s var(--mup-queue-spring), opacity .3s;
  }
  & i:first-child { border-radius: 5px 2px 2px 5px; }
  & i:last-child { border-radius: 2px 5px 5px 2px; }
  & b {
    position: absolute; inset: 0; transform-origin: left; transform: scaleX(var(--mup-queue-p, 0));
    background: color-mix(in oklab, var(--mup-queue-accent) 72%, var(--mup-queue-bg));
  }
  & i[data-s="up"] b { background: var(--mup-queue-accent); }
  & i[data-s="done"] b { background: color-mix(in oklab, var(--mup-queue-accent) 78%, var(--mup-queue-bg)); }
  & i[data-s="fail"] { background: repeating-linear-gradient(-45deg, color-mix(in oklch, var(--mup-queue-fail) 45%, transparent) 0 3px, transparent 0 6px); }
  & i[data-s="fail"] b { background: var(--mup-queue-fail); }
  & i[data-hot] { translate: 0 -2px; box-shadow: 0 0 0 1.5px var(--mup-queue-fg); }
  & i[data-gone] { flex-grow: 0; opacity: 0; min-width: 0; }
}
.mup-queue__stats {
  grid-area: stats; display: flex; flex-wrap: wrap; column-gap: 10px; margin-top: 8px;
  font: 500 11.5px/1.4 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; color: var(--mup-queue-dim);
  & b { color: var(--mup-queue-fg); font-weight: 600; }
  & span + span::before { content: "·"; margin-right: 10px; color: var(--mup-queue-faint); }
}

/* ---------- tools ---------- */
.mup-queue__tools {
  grid-area: tools; display: flex; align-items: center; gap: 6px; margin: 12px 0 8px; padding-bottom: 12px;
  border-bottom: 1px solid var(--mup-queue-line);
}
.mup-queue__btn {
  display: inline-flex; align-items: center; gap: 6px; height: 30px; padding: 0 11px 0 9px; border-radius: 9px;
  background: var(--mup-queue-raise); box-shadow: inset 0 0 0 1px var(--mup-queue-line);
  font-size: 12px; font-weight: 600; white-space: nowrap;
  transition: background-color .15s, scale .3s var(--mup-queue-spring);
  & svg { width: 15px; height: 15px; }
  &:hover { background: color-mix(in oklch, var(--mup-queue-fg) 10%, var(--mup-queue-bg)); }
  &:active { scale: .96; }
  &[hidden] { display: none; }
  & b { font-variant-numeric: tabular-nums; margin-left: 1px; }
}
.mup-queue__btn--warn { color: var(--mup-queue-fail); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--mup-queue-fail) 35%, transparent); }
.mup-queue__btn :is(.mup-queue__gplay, .mup-queue__gagain) { display: none; }
.mup-queue[data-state="paused"] .mup-queue__btn .mup-queue__gpause,
.mup-queue[data-state="done"] .mup-queue__btn .mup-queue__gpause { display: none; }
.mup-queue[data-state="paused"] .mup-queue__btn .mup-queue__gplay { display: inline; }
.mup-queue[data-state="done"] [data-act="pause"] .mup-queue__gagain { display: inline; }
.mup-queue[data-state="paused"] [data-act="pause"] { background: var(--mup-queue-accent); color: var(--mup-queue-on); box-shadow: none; }

.mup-queue__par {
  position: relative; isolation: isolate; display: flex; align-items: center;
  margin-left: auto; padding: 2px; border-radius: 9px; background: var(--mup-queue-well); box-shadow: inset 0 0 0 1px var(--mup-queue-line);
  --mup-queue-c: 2;
  & button {
    position: relative; z-index: 1; width: 26px; height: 26px; border-radius: 7px;
    font: 650 12px/1 ui-monospace, Menlo, monospace; color: var(--mup-queue-dim); transition: color .2s;
  }
  & button[aria-checked="true"] { color: var(--mup-queue-on); }
  & button:hover:not([aria-checked="true"]) { color: var(--mup-queue-fg); }
}
.mup-queue__parlabel { padding: 0 8px 0 7px; font-size: 11px; font-weight: 600; color: var(--mup-queue-dim); }
.mup-queue__thumb {
  position: absolute; z-index: 0; top: 2px; bottom: 2px; right: 2px; width: 26px; border-radius: 7px; background: var(--mup-queue-accent);
  translate: calc((var(--mup-queue-c) - 3) * 26px) 0; transition: translate .45s var(--mup-queue-spring);
}

/* ---------- rows ---------- */
.mup-queue__list {
  grid-area: list; display: grid; max-height: 236px; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin;
  scrollbar-color: var(--mup-queue-faint) transparent; margin: 0 -6px; padding: 0 6px;
}
@supports (animation-timeline: scroll()) {
  .mup-queue__list {
    mask-image: linear-gradient(transparent, #000 var(--mup-queue-ft), #000 calc(100% - var(--mup-queue-fb)), transparent);
    animation: mup-queue-fade linear both; animation-timeline: scroll(self);
  }
  @keyframes mup-queue-fade {
    0% { --mup-queue-ft: 0px; --mup-queue-fb: 22px; }
    12% { --mup-queue-ft: 22px; }
    88% { --mup-queue-fb: 22px; }
    100% { --mup-queue-ft: 22px; --mup-queue-fb: 0px; }
  }
}
.mup-queue__row {
  position: relative;
  display: grid; grid-template-areas: "ico name size acts" "ico msg msg acts"; grid-template-columns: 26px minmax(0, 1fr) auto auto;
  align-items: center; column-gap: 10px; row-gap: 1px; padding: 8px 4px 8px 2px;
  border-bottom: 1px solid var(--mup-queue-line);
  transition: background-color .2s, opacity .3s var(--mup-queue-ease), translate .45s var(--mup-queue-spring);
  transition-delay: 0s, calc(var(--i, 0) * 40ms), calc(var(--i, 0) * 40ms);
  &:last-child { border-bottom: 0; }
  &[data-hot] { background: linear-gradient(90deg, color-mix(in oklch, var(--mup-queue-fg) 5%, transparent), transparent); }
}
@starting-style {
  .mup-queue__row { opacity: 0; translate: 0 6px; }
}
.mup-queue__ico { grid-area: ico; position: relative; display: grid; place-items: center; width: 26px; height: 26px; }
.mup-queue__ring {
  position: absolute; inset: 0; width: 26px; height: 26px; rotate: -90deg;
  & circle { stroke-width: 2.25; }
  & .mup-queue__track { stroke: color-mix(in oklch, var(--mup-queue-fg) 12%, transparent); }
  & .mup-queue__arc { stroke: var(--mup-queue-accent); stroke-dasharray: 100; stroke-dashoffset: 100; transition: stroke .2s; }
}
.mup-queue__glyph { position: relative; width: 14px; height: 14px; stroke-width: 2.5; }
.mup-queue__glyph path { display: none; }
.mup-queue__n { position: absolute; font: 650 10px/1 ui-monospace, Menlo, monospace; color: var(--mup-queue-dim); display: none; }
.mup-queue__row[data-s="wait"] .mup-queue__n { display: block; }
.mup-queue__row[data-s="wait"] .mup-queue__ring .mup-queue__track { stroke-dasharray: 2.4 3.2; }
.mup-queue__row[data-s="hold"] .mup-queue__glyph [data-g="hold"] { display: inline; }
.mup-queue__row[data-s="hold"] .mup-queue__arc { stroke: var(--mup-queue-dim); }
.mup-queue__row[data-s="up"] .mup-queue__ico::after {
  content: ""; position: absolute; inset: 7px; border-radius: 50%; background: var(--mup-queue-accent);
  animation: mup-queue-beat 1.1s var(--mup-queue-ease) infinite;
}
.mup-queue__row[data-s="done"] {
  & .mup-queue__ring .mup-queue__track { stroke: var(--mup-queue-accent); fill: var(--mup-queue-accent); }
  & .mup-queue__arc { opacity: 0; }
  & .mup-queue__glyph { color: var(--mup-queue-on); animation: mup-queue-pop .5s var(--mup-queue-spring); }
  & .mup-queue__glyph [data-g="done"] { display: inline; }
  & .mup-queue__name { color: var(--mup-queue-dim); }
}
.mup-queue__row[data-s="fail"] {
  & .mup-queue__arc { stroke: var(--mup-queue-fail); }
  & .mup-queue__glyph { color: var(--mup-queue-fail); }
  & .mup-queue__glyph [data-g="fail"] { display: inline; }
  & .mup-queue__msg { color: var(--mup-queue-fail); }
}
@keyframes mup-queue-beat { 0% { scale: .4; opacity: .9; } 70%, 100% { scale: 1.6; opacity: 0; } }
@keyframes mup-queue-pop { from { scale: .2; } }

.mup-queue__name { grid-area: name; font-weight: 600; font-size: 13px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; transition: color .3s; }
.mup-queue__size { grid-area: size; font: 500 11.5px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; color: var(--mup-queue-dim); }
.mup-queue__msg {
  grid-area: msg; font-size: 11.5px; color: var(--mup-queue-dim); font-variant-numeric: tabular-nums;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.mup-queue__acts { grid-area: acts; display: flex; gap: 2px; }
.mup-queue__act {
  display: grid; place-items: center; width: 28px; height: 28px; border-radius: 8px; color: var(--mup-queue-dim);
  transition: background-color .15s, color .15s;
  & svg { width: 15px; height: 15px; }
  &:hover { background: color-mix(in oklch, var(--mup-queue-fg) 9%, transparent); color: var(--mup-queue-fg); }
  &[data-a="retry"] { color: var(--mup-queue-fail); }
  &[data-a="retry"]:hover { background: color-mix(in oklch, var(--mup-queue-fail) 16%, transparent); }
}
.mup-queue__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

@container (max-width: 340px) {
  .mup-queue__parlabel { display: none; }
  .mup-queue__btn { padding: 0 9px 0 8px; }
}
@container (max-width: 300px) {
  .mup-queue__tools { flex-wrap: wrap; }
  .mup-queue__row { column-gap: 8px; }
}
@container (min-width: 400px) {
  .mup-queue__row { grid-template-areas: "ico name size acts" "ico msg msg acts"; padding-block: 9px; }
  .mup-queue__bar { height: 12px; }
}

@media (prefers-reduced-motion: reduce) {
  .mup-queue__pct b { transition: none; }
  .mup-queue__bar i, .mup-queue__thumb, .mup-queue__row, .mup-queue__btn { transition-duration: .01s; transition-delay: 0s; }
  .mup-queue__row[data-s="up"] .mup-queue__ico::after { animation: none; scale: .55; opacity: .9; }
  .mup-queue__row[data-s="done"] .mup-queue__glyph { animation: none; }
  .mup-queue__bar i[data-hot] { translate: 0 0; }
}

