const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const later = (ms, fn) => setTimeout(() => { if (root.isConnected) fn(); }, ms);
const EASE = 'cubic-bezier(.22,1,.36,1)';

/* name, MB, and an optional first-attempt failure: where it breaks, why, and whether the partial bytes survive */
const SOURCE = [
  { name: 'site14-overview.jpg', mb: 4.8, seed: 1 },
  { name: 'drone-pass-03.mp4', mb: 38.2, seed: 0.14, failAt: 0.62, why: 'Connection reset', keep: true },
  { name: 'soil-cores.csv', mb: 0.6, seed: 0.7 },
  { name: 'permit-scan.pdf', mb: 2.4, failAt: 1, why: 'Checksum mismatch', keep: false },
  { name: 'crack-survey-north.jpg', mb: 6.1 },
  { name: 'crack-survey-south.jpg', mb: 5.9 },
  { name: 'inspection-notes.docx', mb: 1.2 }
];
const STREAM = 3.1e6, LINK = 7.2e6;

const list = $('.mup-queue__list'), bar = $('.mup-queue__bar'), live = $('.mup-queue__sr');
const titleEl = $('[data-title]'), pctEl = $('[data-pct]'), statsEl = $('[data-stats]');
const pauseBtn = $('[data-act="pause"]'), pauseLabel = $('[data-pause-label]');
const retryAll = $('[data-act="retry-all"]'), failedN = $('[data-failed]');
const par = $('.mup-queue__par'), radios = $$('[role="radio"]', par);

let files = [], conc = 2, paused = false, raf = 0, last = 0, onscreen = true, rate = 0, elapsed = 0, pctShown = -1;

const say = (m) => { live.textContent = ''; later(40, () => { live.textContent = m; }); };
const mb = (b) => (b / 1e6).toFixed(1);
const secs = (s) => s >= 60 ? Math.floor(s / 60) + 'm ' + String(Math.round(s % 60)).padStart(2, '0') + 's' : Math.max(1, Math.round(s)) + 's';
const plural = (n, w) => n + ' ' + w + (n === 1 ? '' : 's');

const ICON = {
  x: '<svg viewBox="0 0 24 24"><path d="M7 7l10 10M17 7 7 17"/></svg>',
  retry: '<svg viewBox="0 0 24 24"><path d="M18.5 12a6.5 6.5 0 1 1-1.9-4.6M18.5 4.5v3.2h-3.2"/></svg>'
};

function build() {
  list.replaceChildren(); bar.replaceChildren();
  files = SOURCE.map((s, i) => {
    const size = Math.round(s.mb * 1e6);
    const f = { ...s, id: i, size, sent: (s.seed || 0) * size, s: s.seed === 1 ? 'done' : s.seed ? 'up' : 'wait', attempt: 1, took: s.seed === 1 ? 1.6 : 0, t0: s.seed ? 0 : null, v: 0, shown: '' };
    const li = document.createElement('li');
    li.className = 'mup-queue__row';
    li.style.setProperty('--i', i);
    li.innerHTML =
      '<span class="mup-queue__ico" aria-hidden="true"><svg class="mup-queue__ring" viewBox="0 0 24 24"><circle class="mup-queue__track" cx="12" cy="12" r="10"/><circle class="mup-queue__arc" cx="12" cy="12" r="10" pathLength="100"/></svg>' +
      '<svg class="mup-queue__glyph" viewBox="0 0 24 24"><path data-g="done" d="m6 12.5 4 4 8-9"/><path data-g="fail" d="M12 6.5v7M12 17.5v.01"/><path data-g="hold" d="M9.5 7v10M14.5 7v10"/></svg><b class="mup-queue__n"></b></span>' +
      '<span class="mup-queue__name"></span><span class="mup-queue__size"></span><span class="mup-queue__msg"></span><span class="mup-queue__acts"></span>';
    $('.mup-queue__name', li).textContent = f.name;
    $('.mup-queue__size', li).textContent = mb(size) + ' MB';
    const seg = document.createElement('i');
    seg.style.setProperty('--mup-queue-w', s.mb);
    seg.innerHTML = '<b></b>';
    f.el = li; f.seg = seg; f.arc = $('.mup-queue__arc', li); f.msg = $('.mup-queue__msg', li); f.n = $('.mup-queue__n', li); f.acts = $('.mup-queue__acts', li);
    list.append(li); bar.append(seg);
    later(700, () => li.style.removeProperty('--i'));
    return f;
  });
  elapsed = 0; rate = 0; paused = false;
}

/* ---------- painting ---------- */
function paint(f, waitPos) {
  const p = f.sent / f.size;
  f.el.dataset.s = f.s; f.seg.dataset.s = f.s;
  f.seg.style.setProperty('--mup-queue-p', p.toFixed(4));
  f.arc.style.strokeDashoffset = (100 - p * 100).toFixed(2);
  const pct = Math.floor(p * 100);
  let msg = '';
  if (f.s === 'wait') msg = (waitPos === 1 ? 'Up next' : 'Queued · ' + (waitPos - 1) + ' ahead') + (f.sent ? ' · resumes at ' + pct + '%' : '');
  else if (f.s === 'up') msg = pct + '% · ' + (f.v / 1e6).toFixed(1) + ' MB/s · ' + secs((f.size - f.sent) / Math.max(f.v, 1)) + ' left';
  else if (f.s === 'hold') msg = 'Paused at ' + pct + '%';
  else if (f.s === 'fail') msg = f.keep ? f.why + ' at ' + pct + '% · resumable' : f.why + ' · re-sends ' + mb(f.size) + ' MB';
  else msg = (f.attempt > 1 ? 'Uploaded on attempt ' + f.attempt : 'Uploaded') + ' in ' + secs(f.took);
  if (msg !== f.msgText) { f.msg.textContent = msg; f.msgText = msg; }
  f.n.textContent = f.s === 'wait' ? waitPos : '';
  if (f.shown !== f.s) {
    f.shown = f.s;
    const a = [];
    if (f.s === 'fail') a.push('<button type="button" class="mup-queue__act" data-a="retry" aria-label="Retry ' + f.name + '">' + ICON.retry + '</button>');
    if (f.s !== 'done') a.push('<button type="button" class="mup-queue__act" data-a="remove" aria-label="' + (f.s === 'up' ? 'Cancel ' : 'Remove ') + f.name + '">' + ICON.x + '</button>');
    const had = f.acts.contains(document.activeElement);
    f.acts.innerHTML = a.join('');
    if (had) (f.acts.querySelector('button') || nearestButton(f) || pauseBtn).focus();
  }
}
function nearestButton(f) {
  const k = files.indexOf(f);
  for (let d = 1; d < files.length; d++) {
    for (const j of [k + d, k - d]) { const b = files[j] && files[j].acts.querySelector('button'); if (b) return b; }
  }
  return null;
}

function summary() {
  const total = files.reduce((a, f) => a + f.size, 0), sent = files.reduce((a, f) => a + f.sent, 0);
  const done = files.filter((f) => f.s === 'done').length, failed = files.filter((f) => f.s === 'fail').length;
  const moving = files.some((f) => f.s === 'up' || f.s === 'wait' || f.s === 'hold');
  const state = !files.length ? 'done' : paused && moving ? 'paused' : moving ? 'run' : failed ? 'stuck' : 'done';
  const pct = total ? Math.floor((sent / total) * 100) : 100;
  root.dataset.state = state;
  pctEl.style.setProperty('--mup-queue-n', pct);
  if (pct !== pctShown) { pctShown = pct; bar.setAttribute('aria-valuenow', pct); bar.setAttribute('aria-valuetext', pct + '%, ' + done + ' of ' + files.length + ' files uploaded'); }
  titleEl.textContent =
    state === 'run' ? 'Uploading ' + done + ' of ' + files.length :
    state === 'paused' ? 'Paused · ' + done + ' of ' + files.length + ' done' :
    state === 'stuck' ? plural(failed, 'upload') + ' need' + (failed === 1 ? 's' : '') + ' attention' :
    files.length ? 'All ' + plural(files.length, 'file') + ' uploaded' : 'Queue is empty';
  const left = total - sent;
  let s = '<span><b>' + mb(sent) + '</b> of ' + mb(total) + ' MB</span>';
  if (state === 'run') s += '<span>' + (rate / 1e6).toFixed(1) + ' MB/s</span><span>' + (rate > 1e5 ? secs(left / rate) + ' left' : 'starting') + '</span>';
  else if (state === 'paused') s += '<span>paused</span>';
  else if (state === 'done' && files.length) s += '<span>in ' + secs(elapsed) + '</span>';
  else if (state === 'stuck') s += '<span>' + mb(left) + ' MB to go</span>';
  if (s !== statsEl.innerHTML) statsEl.innerHTML = s;
  pauseLabel.textContent = state === 'paused' ? 'Resume all' : state === 'done' ? 'Run again' : 'Pause all';
  pauseBtn.disabled = state === 'stuck';
  pauseBtn.hidden = state === 'stuck';
  retryAll.hidden = !failed;
  failedN.textContent = failed;
  return state;
}

/* ---------- scheduler ---------- */
function schedule() {
  if (paused) return;
  let active = files.filter((f) => f.s === 'up');
  for (const f of active.slice(conc)) f.s = 'wait';
  active = active.slice(0, conc);
  for (const f of files) {
    if (active.length >= conc) break;
    if (f.s === 'wait') { f.s = 'up'; if (f.t0 == null) f.t0 = elapsed; f.v = 0; active.push(f); }
  }
}
function paintAll() {
  let w = 0;
  for (const f of files) paint(f, f.s === 'wait' ? ++w : 0);
  return summary();
}
function tick(t) {
  if (!root.isConnected) { io.disconnect(); return; }
  raf = 0;
  const dt = Math.min(0.1, (t - last) / 1000);
  last = t;
  elapsed += dt;
  const active = files.filter((f) => f.s === 'up');
  const share = Math.min(STREAM, LINK / Math.max(1, active.length));
  let moved = 0;
  for (const f of active) {
    const wob = 0.8 + 0.4 * Math.abs(Math.sin(t / 530 + f.id * 1.7));
    const step = share * wob * dt;
    f.v = f.v ? f.v * 0.9 + share * wob * 0.1 : share * wob;
    f.sent = Math.min(f.size, f.sent + step);
    moved += step;
    if (f.failAt != null && f.attempt === 1 && f.sent >= f.failAt * f.size) {
      f.sent = f.failAt * f.size;
      f.s = 'fail';
      say(f.name + ' failed: ' + f.why + '.');
    } else if (f.sent >= f.size) {
      f.s = 'done'; f.took = elapsed - f.t0;
      say(f.name + ' uploaded.');
    }
  }
  rate = rate * 0.92 + (dt ? moved / dt : 0) * 0.08;
  schedule();
  const state = paintAll();
  if (state === 'done' && files.length) say('All ' + plural(files.length, 'file') + ' uploaded.');
  if (state === 'stuck') say(titleEl.textContent + '.');
  if (state === 'run') loop();
}
function loop() {
  if (raf || !onscreen) return;
  last = performance.now();
  raf = requestAnimationFrame(tick);
}

/* ---------- actions ---------- */
function retry(f) {
  if (f.s !== 'fail') return;
  if (!f.keep) f.sent = 0;
  f.s = 'wait';
  f.attempt++;
  say('Retrying ' + f.name + (f.keep ? ' from ' + Math.floor((f.sent / f.size) * 100) + '%.' : ' from the start.'));
}
function remove(f, refocus) {
  const k = files.indexOf(f);
  if (k < 0) return;
  const wasUp = f.s === 'up';
  files.splice(k, 1);
  const rows = files.map((x) => x.el), before = rows.map((el) => el.getBoundingClientRect().top);
  f.seg.dataset.gone = '';
  later(RM.matches ? 0 : 520, () => f.seg.remove());
  f.el.remove();
  if (!RM.matches) rows.forEach((el, j) => {
    const dy = before[j] - el.getBoundingClientRect().top;
    if (dy) el.animate([{ transform: 'translateY(' + dy + 'px)' }, { transform: 'none' }], { duration: 420, easing: EASE });
  });
  say((wasUp ? 'Cancelled ' : 'Removed ') + f.name + '.');
  schedule(); paintAll(); loop();
  if (refocus) (nearestButton(files[Math.min(k, files.length - 1)] || f) || pauseBtn).focus();
}
function setPaused(v) {
  paused = v;
  for (const f of files) {
    if (v && f.s === 'up') f.s = 'hold';
    else if (!v && f.s === 'hold') f.s = 'up';
  }
  if (!v) { rate = 0; schedule(); }
  paintAll();
  say(v ? 'Paused. Uploaded bytes are kept.' : 'Resumed.');
  if (!v) loop();
}
function setConc(c, focus) {
  conc = c;
  par.style.setProperty('--mup-queue-c', c);
  radios.forEach((r) => {
    const on = +r.dataset.c === c;
    r.setAttribute('aria-checked', String(on));
    r.tabIndex = on ? 0 : -1;
    if (on && focus) r.focus();
  });
  for (const f of files.filter((x) => x.s === 'up').slice(c)) f.s = 'wait';
  schedule(); paintAll(); loop();
}

pauseBtn.addEventListener('click', () => {
  const st = root.dataset.state;
  if (st === 'done') {
    build(); schedule(); paintAll(); loop();
    say('Queue restarted.');
  } else setPaused(st !== 'paused');
});
retryAll.addEventListener('click', () => {
  const failed = files.filter((f) => f.s === 'fail');
  failed.forEach(retry);
  if (paused) setPaused(false); else { schedule(); paintAll(); loop(); }
  say('Retrying ' + plural(failed.length, 'file') + '.');
  pauseBtn.focus();
});
list.addEventListener('click', (e) => {
  const b = e.target.closest('.mup-queue__act');
  if (!b) return;
  const f = files.find((x) => x.acts.contains(b));
  if (!f) return;
  if (b.dataset.a === 'retry') { retry(f); schedule(); paintAll(); loop(); }
  else remove(f, true);
});
list.addEventListener('keydown', (e) => {
  const btns = $$('.mup-queue__act', list);
  const k = btns.indexOf(document.activeElement);
  if (k < 0) return;
  const row = btns[k].closest('li');
  const rowsWith = files.filter((f) => f.acts.querySelector('button'));
  const r = rowsWith.findIndex((f) => f.el === row);
  if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
    e.preventDefault();
    const next = rowsWith[r + (e.key === 'ArrowDown' ? 1 : -1)];
    if (next) next.acts.querySelector('button').focus();
  } else if (e.key === 'ArrowLeft' || e.key === 'ArrowRight') {
    const inRow = [...row.querySelectorAll('button')], j = inRow.indexOf(btns[k]);
    const n = inRow[j + (e.key === 'ArrowRight' ? 1 : -1)];
    if (n) { e.preventDefault(); n.focus(); }
  } else if (e.key === 'Delete' || e.key === 'Backspace') {
    e.preventDefault();
    const f = files.find((x) => x.el === row);
    if (f) remove(f, true);
  }
});
par.addEventListener('click', (e) => { const r = e.target.closest('[role="radio"]'); if (r) setConc(+r.dataset.c, false); });
par.addEventListener('keydown', (e) => {
  const d = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 }[e.key];
  if (d) { e.preventDefault(); setConc(Math.min(3, Math.max(1, conc + d)), true); }
  else if (e.key === 'Home' || e.key === 'End') { e.preventDefault(); setConc(e.key === 'Home' ? 1 : 3, true); }
});

/* row <-> segment: pointing at either lights both */
function hot(f) {
  files.forEach((x) => { x.el.toggleAttribute('data-hot', x === f); x.seg.toggleAttribute('data-hot', x === f); });
}
const fileOf = (el) => files.find((f) => f.el.contains(el) || f.seg === el);
list.addEventListener('pointerover', (e) => hot(fileOf(e.target)));
bar.addEventListener('pointerover', (e) => hot(fileOf(e.target.closest('i'))));
list.addEventListener('focusin', (e) => hot(fileOf(e.target)));
list.addEventListener('pointerleave', () => hot(null));
bar.addEventListener('pointerleave', () => hot(null));
list.addEventListener('focusout', (e) => { if (!list.contains(e.relatedTarget)) hot(null); });

const io = new IntersectionObserver((es) => {
  if (!root.isConnected) { io.disconnect(); return; }
  onscreen = es[es.length - 1].isIntersecting;
  if (onscreen && root.dataset.state === 'run') loop();
});
io.observe(root);

build();
schedule();
paintAll();
loop();

css:
@property --mup-crop-veil {
  syntax: "<number>";
  inherits: true;
  initial-value: 0.62;
}

/* Re-theme with --mup-crop-bg, -ink, -accent and -stage. */
.mup-crop {
  --mup-crop-bg: oklch(0.975 0.011 70);
  --mup-crop-ink: oklch(0.27 0.03 40);
  --mup-crop-accent: oklch(0.6 0.15 38);
  --mup-crop-stage: oklch(0.27 0.018 45);

  --mup-crop-dim: color-mix(in oklab, var(--mup-crop-ink) 58%, var(--mup-crop-bg));
  --mup-crop-faint: color-mix(in oklab, var(--mup-crop-ink) 30%, var(--mup-crop-bg));
  --mup-crop-line: color-mix(in oklab, var(--mup-crop-ink) 12%, var(--mup-crop-bg));
  --mup-crop-raise: color-mix(in oklch, white 70%, var(--mup-crop-bg));
  --mup-crop-danger: oklch(0.55 0.19 25);
  --mup-crop-ease: cubic-bezier(.22, 1, .36, 1);
  --mup-crop-spring: linear(0, 0.034 2.3%, 0.13 4.7%, 0.484 11.6%, 0.656 15.5%, 0.786 19.5%, 0.883 23.6%, 0.951 27.9%, 1.006 33.3%, 1.03 38.5%, 1.037 44.2%, 1.025 54.1%, 1.008 66.8%, 1);

  container-type: inline-size;
  position: relative;
  display: grid;
  grid-template-areas: "head" "stage" "tools" "foot";
  grid-template-columns: minmax(0, 1fr);
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  padding: 14px;
  border-radius: 20px;
  background: var(--mup-crop-bg);
  color: var(--mup-crop-ink);
  box-shadow: 0 0 0 1px var(--mup-crop-line), 0 20px 44px -30px color-mix(in oklch, var(--mup-crop-ink) 70%, transparent);
  font: 400 13px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-align: left;
  accent-color: var(--mup-crop-accent);
}
@supports not (transition-timing-function: linear(0, 1)) {
  .mup-crop { --mup-crop-spring: cubic-bezier(.3, 1.35, .5, 1); }
}
:where(.mup-crop) *, :where(.mup-crop) *::before, :where(.mup-crop) *::after { box-sizing: border-box; }
:where(.mup-crop) :is(p, h3, ul, li) { margin: 0; padding: 0; list-style: none; }
:where(.mup-crop) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
:where(.mup-crop) :focus-visible { outline: 2px solid var(--mup-crop-accent); outline-offset: 2px; }
.mup-crop svg { fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }

.mup-crop__head {
  grid-area: head; display: flex; align-items: end; justify-content: space-between; gap: 10px; margin-bottom: 12px;
  & div { min-width: 0; }
  & h3 { font-size: clamp(15px, 5cqi, 18px); font-weight: 700; letter-spacing: -.015em; line-height: 1.15; text-wrap: balance; }
}
.mup-crop__eyebrow {
  font-size: 10.5px; font-weight: 650; letter-spacing: .1em; text-transform: uppercase; color: var(--mup-crop-dim);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; margin-bottom: 3px;
}
.mup-crop__ghost {
  display: inline-flex; align-items: center; gap: 6px; height: 30px; padding: 0 11px 0 9px; border-radius: 9px; flex: none;
  font-size: 12px; font-weight: 600; background: var(--mup-crop-raise); box-shadow: inset 0 0 0 1px var(--mup-crop-line);
  transition: background-color .15s, scale .3s var(--mup-crop-spring);
  & svg { width: 15px; height: 15px; }
  &:hover { background: color-mix(in oklch, var(--mup-crop-ink) 6%, var(--mup-crop-raise)); }
  &:active { scale: .96; }
}

/* ---------- stage ---------- */
.mup-crop__stage {
  grid-area: stage; position: relative; overflow: hidden; isolation: isolate;
