    const li = makeItem(m);
    list.insertBefore(li, addLi);
    const cv = $('canvas', li);
    createImageBitmap(f).then((bmp) => {
      if (!root.isConnected) { bmp.close(); return; }
      const s = Math.max(320 / bmp.width, 320 / bmp.height);
      cv.getContext('2d').drawImage(bmp, (320 - bmp.width * s) / 2, (320 - bmp.height * s) / 2, bmp.width * s, bmp.height * s);
      bmp.close();
    }).catch(() => {
      if (!root.isConnected || !byId[m.id]) return;
      m.state = 'err'; li.dataset.s = 'err';
      $('.mup-grid__cap', li).textContent = 'Couldn’t read ' + f.name;
      renumber();
      say('Couldn’t read ' + f.name + '. Remove it or try another file.');
    });
  }
  renumber();
  kick();
  let msg = take.length ? plural(take.length, 'photo') + ' added.' : 'No photos added.';
  if (skipped) msg += ' ' + plural(skipped, 'file') + (room <= imgs.length && imgs.length > take.length ? ' skipped, the sheet holds ' + MAXN + '.' : ' skipped, only images are accepted.');
  say(msg);
}
addBtn.addEventListener('click', () => input.click());
input.addEventListener('change', () => { if (input.files.length) addFiles([...input.files]); input.value = ''; });

let depth = 0;
const hasFiles = (e) => !!e.dataTransfer && [...e.dataTransfer.types].includes('Files');
root.addEventListener('dragenter', (e) => {
  if (!hasFiles(e)) return;
  e.preventDefault();
  if (++depth === 1) {
    const n = [...e.dataTransfer.items].filter((it) => it.kind === 'file').length, room = MAXN - sortable().length;
    overTxt.textContent = room <= 0 ? 'The sheet is full · ' + MAXN + ' frames' : 'Drop to add ' + plural(Math.min(n || 1, room), 'photo');
    root.setAttribute('data-over', '');
  }
});
root.addEventListener('dragover', (e) => { if (!hasFiles(e)) return; e.preventDefault(); e.dataTransfer.dropEffect = 'copy'; });
root.addEventListener('dragleave', (e) => { if (!hasFiles(e)) return; if (--depth <= 0) { depth = 0; root.removeAttribute('data-over'); } });
root.addEventListener('drop', (e) => {
  if (!hasFiles(e)) return;
  e.preventDefault(); depth = 0; root.removeAttribute('data-over');
  addFiles([...e.dataTransfer.files]);
});

/* ---------- save and reset ---------- */
saveBtn.addEventListener('click', () => {
  if (saveBtn.disabled) return;
  state = 'saving';
  if (removed) dropUndo();
  sync();
  later(RM.matches ? 300 : 900, () => {
    saved = order();
    moves = 0;
    state = 'saved';
    sync();
    say('Sequence saved. The cover is ' + model(sortable()[0]).t + '.');
  });
});
resetBtn.addEventListener('click', () => {
  const rank = (id) => { const k = saved.indexOf(id); return k < 0 ? 1e3 : k; };
  const sorted = sortable().sort((a, b) => rank(a.dataset.id) - rank(b.dataset.id));
  flip(() => sorted.forEach((li) => list.insertBefore(li, addLi)));
  moves = 0;
  if (removed) dropUndo();
  renumber();
  say('Order reset to the last saved sequence.');
});

const io = new IntersectionObserver((es) => {
  if (!root.isConnected) { io.disconnect(); return; }
  onscreen = es[es.length - 1].isIntersecting;
  if (onscreen) kick();
});
io.observe(root);
renumber();
kick();

