@property --mup-paste-a {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}
@property --mup-paste-fl { syntax: "<length>"; inherits: false; initial-value: 0px; }
@property --mup-paste-fr { syntax: "<length>"; inherits: false; initial-value: 0px; }
@property --mup-paste-ring {
  syntax: "<color>";
  inherits: false;
  initial-value: transparent;
}
@property --mup-paste-sweep {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}

/* Re-theme with --mup-paste-bg, -ink, -accent and -danger. */
.mup-paste {
  --mup-paste-bg: oklch(0.982 0.005 250);
  --mup-paste-ink: oklch(0.25 0.025 258);
  --mup-paste-accent: oklch(0.53 0.165 258);
  --mup-paste-danger: oklch(0.56 0.19 25);

  --mup-paste-dim: color-mix(in oklch, var(--mup-paste-ink) 58%, var(--mup-paste-bg));
  --mup-paste-faint: color-mix(in oklch, var(--mup-paste-ink) 32%, var(--mup-paste-bg));
  --mup-paste-line: color-mix(in oklch, var(--mup-paste-ink) 12%, var(--mup-paste-bg));
  --mup-paste-paper: color-mix(in oklch, white 80%, var(--mup-paste-bg));
  --mup-paste-tint: color-mix(in oklch, var(--mup-paste-accent) 9%, var(--mup-paste-paper));
  --mup-paste-ease: cubic-bezier(.22, 1, .36, 1);
  --mup-paste-spring: linear(0, 0.034 2.3%, 0.13 4.7%, 0.484 11.6%, 0.656 15.5%, 0.786 19.5%, 0.883 23.6%, 0.951 27.9%, 1.006 33.3%, 1.03 38.5%, 1.037 44.2%, 1.025 54.1%, 1.008 66.8%, 1);

  container-type: inline-size;
  position: relative;
  display: grid;
  grid-template-areas: "head" "sent" "box" "try";
  grid-template-columns: minmax(0, 1fr);
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  padding: 14px;
  border-radius: 18px;
  background: var(--mup-paste-bg);
  color: var(--mup-paste-ink);
  box-shadow: 0 0 0 1px var(--mup-paste-line), 0 18px 40px -30px color-mix(in oklch, var(--mup-paste-ink) 70%, transparent);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-align: left;
  accent-color: var(--mup-paste-accent);
}
@supports not (transition-timing-function: linear(0, 1)) {
  .mup-paste { --mup-paste-spring: cubic-bezier(.3, 1.35, .5, 1); }
}
:where(.mup-paste) *, :where(.mup-paste) *::before, :where(.mup-paste) *::after { box-sizing: border-box; }
:where(.mup-paste) :is(p, h3, ul, li) { margin: 0; padding: 0; list-style: none; }
:where(.mup-paste) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
:where(.mup-paste) :focus-visible { outline: 2px solid var(--mup-paste-accent); outline-offset: 2px; }
.mup-paste .mup-paste__i { fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }

.mup-paste__head {
  grid-area: head; display: grid; grid-template-columns: auto minmax(0, 1fr); align-items: center; gap: 10px; margin-bottom: 12px;
  & h3 { font-size: clamp(14px, 4.5cqi, 16.5px); font-weight: 700; letter-spacing: -.012em; line-height: 1.2; text-wrap: balance; }
}
.mup-paste__av {
  display: grid; place-items: center; width: 34px; height: 34px; border-radius: 50%;
  font-size: 12px; font-weight: 700; letter-spacing: .02em; color: var(--mup-paste-accent);
  background: color-mix(in oklch, var(--mup-paste-accent) 13%, var(--mup-paste-bg));
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--mup-paste-accent) 22%, transparent);
}
.mup-paste__eyebrow {
  font-size: 10.5px; font-weight: 650; letter-spacing: .09em; text-transform: uppercase; color: var(--mup-paste-dim);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; margin-bottom: 2px;
}

/* receipt after sending */
.mup-paste__sent {
  grid-area: sent; display: flex; align-items: center; gap: 7px; overflow: hidden;
  font-size: 12px; font-weight: 600; color: color-mix(in oklch, oklch(0.55 0.13 155) 80%, var(--mup-paste-ink));
  max-height: 0; opacity: 0; translate: 0 -6px;
  transition: max-height .4s var(--mup-paste-ease), opacity .25s, translate .45s var(--mup-paste-spring), margin .4s var(--mup-paste-ease);
  & svg { width: 16px; height: 16px; stroke-width: 2.2; }
}
.mup-paste[data-sent] .mup-paste__sent { max-height: 24px; opacity: 1; translate: 0 0; margin-bottom: 10px; }

/* ---------- the composer surface ---------- */
.mup-paste__box {
  grid-area: box; position: relative; isolation: isolate; display: grid; grid-template-columns: minmax(0, 1fr);
  border-radius: 14px; background: var(--mup-paste-paper);
  box-shadow: 0 0 0 1px var(--mup-paste-line), 0 1px 2px color-mix(in oklch, var(--mup-paste-ink) 6%, transparent);
  transition: box-shadow .2s;
  &:focus-within { box-shadow: 0 0 0 1px color-mix(in oklch, var(--mup-paste-accent) 55%, transparent), 0 0 0 4px color-mix(in oklch, var(--mup-paste-accent) 13%, transparent); }
  .mup-paste[data-over] & { box-shadow: 0 0 0 2px var(--mup-paste-accent), 0 0 0 6px color-mix(in oklch, var(--mup-paste-accent) 16%, transparent); background: var(--mup-paste-tint); }
  /* a light runs once around the border when something is pasted */
  &::after {
    content: ""; position: absolute; inset: -1px; z-index: 3; border-radius: 15px; padding: 1.5px; pointer-events: none;
    background: conic-gradient(from var(--mup-paste-sweep), transparent 0 70%, var(--mup-paste-accent) 88%, transparent 100%);
    mask: linear-gradient(#000 0 0) content-box exclude, linear-gradient(#000 0 0);
    opacity: 0;
  }
}
.mup-paste[data-flash] .mup-paste__box::after { animation: mup-paste-sweep .9s var(--mup-paste-ease); }
@keyframes mup-paste-sweep {
  0% { opacity: 1; --mup-paste-sweep: 0deg; }
  80% { opacity: 1; }
  100% { opacity: 0; --mup-paste-sweep: 360deg; }
}

.mup-paste__tray {
  display: flex; gap: 6px; overflow-x: auto; overscroll-behavior-x: contain; scroll-snap-type: x proximity; scroll-padding-inline: 8px;
  scrollbar-width: none;
  &::-webkit-scrollbar { display: none; }
  &:not(:empty) { padding: 8px 8px 2px; }
  & > li { flex: 0 0 min(222px, 86%); scroll-snap-align: start; }
}
@supports (animation-timeline: scroll()) {
  .mup-paste__tray {
    mask-image: linear-gradient(90deg, transparent, #000 var(--mup-paste-fl), #000 calc(100% - var(--mup-paste-fr)), transparent);
    animation: mup-paste-edges linear both; animation-timeline: scroll(self inline);
  }
  @keyframes mup-paste-edges {
    0% { --mup-paste-fl: 0px; --mup-paste-fr: 22px; }
    8% { --mup-paste-fl: 22px; }
    92% { --mup-paste-fr: 22px; }
    100% { --mup-paste-fl: 22px; --mup-paste-fr: 0px; }
  }
}
.mup-paste__chip {
  position: relative; display: grid; grid-template-areas: "thumb name x" "thumb meta x"; grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center; column-gap: 9px; padding: 6px 4px 6px 6px; border-radius: 10px;
  background: var(--mup-paste-bg); box-shadow: inset 0 0 0 1px var(--mup-paste-line);
  transition: opacity .35s var(--mup-paste-ease), scale .5s var(--mup-paste-spring), filter .35s var(--mup-paste-ease), background-color .3s, box-shadow .3s;
  &:has(.mup-paste__x:focus-visible) { box-shadow: inset 0 0 0 1.5px var(--mup-paste-accent); }
}
@starting-style {
  .mup-paste__chip { opacity: 0; scale: .86; filter: blur(4px); }
}
.mup-paste__chip[data-out] { opacity: 0; scale: .9; filter: blur(3px); transition-duration: .2s; }

/* the thumbnail wears its progress as a conic ring on a registered <angle> */
.mup-paste__thumb {
  grid-area: thumb; position: relative; display: grid; place-items: center; width: 40px; height: 40px; border-radius: 9px; padding: 2.5px;
  --mup-paste-ring: var(--mup-paste-accent);
  background: conic-gradient(var(--mup-paste-ring) var(--mup-paste-a), var(--mup-paste-line) 0);
  transition: --mup-paste-a .45s linear, --mup-paste-ring .6s var(--mup-paste-ease) .25s;
  & canvas, & .mup-paste__doc { display: block; width: 100%; height: 100%; border-radius: 6.5px; background: var(--mup-paste-paper); }
  & canvas { box-shadow: 0 0 0 1.5px var(--mup-paste-bg); }
}
.mup-paste__doc {
  display: grid !important; align-content: center; justify-items: center; gap: 1px;
  font: 700 8.5px/1 ui-monospace, Menlo, monospace; letter-spacing: .04em; color: var(--mup-paste-accent);
  box-shadow: 0 0 0 1.5px var(--mup-paste-bg);
  & small { font-size: 7.5px; font-weight: 600; color: var(--mup-paste-dim); letter-spacing: 0; }
}
.mup-paste__chip[data-s="done"] .mup-paste__thumb { --mup-paste-ring: var(--mup-paste-line); }
.mup-paste__chip[data-s="err"] .mup-paste__thumb { --mup-paste-ring: var(--mup-paste-danger); --mup-paste-a: 360deg; transition: none; }
.mup-paste__chip[data-s="err"] .mup-paste__doc { color: var(--mup-paste-danger); }
.mup-paste__name { grid-area: name; font-size: 12px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mup-paste__meta {
  grid-area: meta; font-size: 11px; color: var(--mup-paste-dim); font-variant-numeric: tabular-nums;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.mup-paste__chip[data-s="err"] {
  background: color-mix(in oklab, var(--mup-paste-danger) 6%, var(--mup-paste-bg));
  box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--mup-paste-danger) 30%, transparent);
  & .mup-paste__meta { color: var(--mup-paste-danger); font-weight: 550; white-space: normal; line-height: 1.25; }
}
.mup-paste__x {
  grid-area: x; display: grid; place-items: center; width: 26px; height: 26px; border-radius: 7px; color: var(--mup-paste-dim);
  transition: background-color .15s, color .15s;
  & svg { width: 14px; height: 14px; }
  &:hover { background: color-mix(in oklch, var(--mup-paste-ink) 7%, transparent); color: var(--mup-paste-ink); }
}

.mup-paste__field {
  display: block; width: 100%; min-height: calc(3lh + 20px); max-height: calc(7lh + 20px); field-sizing: content; resize: none;
  padding: 10px 12px; border: 0; outline: none; background: transparent; color: inherit;
  font: inherit; font-size: 13.5px; line-height: 1.45;
  &::placeholder { color: var(--mup-paste-faint); }
}

/* fold notice: a long paste became a file, offer the inline route */
.mup-paste__fold {
  display: flex; align-items: center; gap: 7px; margin: 0 8px; padding: 0 4px 0 8px; border-radius: 8px; overflow: hidden;
  font-size: 11.5px; color: var(--mup-paste-ink); background: var(--mup-paste-tint);
  max-height: 0; opacity: 0;
  transition: max-height .35s var(--mup-paste-ease), opacity .2s, margin .35s var(--mup-paste-ease);
  & svg { width: 15px; height: 15px; color: var(--mup-paste-accent); }
  & span { flex: 1; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & button { flex: none; height: 26px; padding: 0 8px; border-radius: 6px; font-weight: 650; color: var(--mup-paste-accent); }
  & button:hover { background: color-mix(in oklch, var(--mup-paste-accent) 12%, transparent); }
}
.mup-paste[data-fold] .mup-paste__fold { max-height: 34px; opacity: 1; margin-bottom: 6px; }

.mup-paste__bar {
  display: flex; align-items: center; gap: 6px; padding: 6px 6px 6px 4px;
  border-top: 1px solid color-mix(in oklch, var(--mup-paste-ink) 7%, transparent);
}
.mup-paste__icon {
  display: grid; place-items: center; width: 32px; height: 32px; border-radius: 8px; color: var(--mup-paste-dim); flex: none;
  transition: background-color .15s, color .15s, rotate .45s var(--mup-paste-spring);
  & svg { width: 18px; height: 18px; }
  &:hover { background: color-mix(in oklch, var(--mup-paste-ink) 6%, transparent); color: var(--mup-paste-ink); rotate: -12deg; }
}
.mup-paste__hint {
  flex: 1; min-width: 0; font-size: 11.5px; color: var(--mup-paste-dim); white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  & kbd {
    display: inline-block; min-width: 18px; padding: 1px 4px; margin-right: 2px; border-radius: 4px; text-align: center;
    font: 600 10.5px/1.35 system-ui, sans-serif; color: var(--mup-paste-ink);
    background: var(--mup-paste-bg); box-shadow: inset 0 -1px 0 var(--mup-paste-line), 0 0 0 1px var(--mup-paste-line);
  }
  & b { color: var(--mup-paste-danger); font-weight: 600; }
}
.mup-paste__send {
  flex: none; display: inline-flex; align-items: center; gap: 6px; height: 32px; padding: 0 10px 0 13px; border-radius: 9px;
  font-size: 12.5px; font-weight: 650; color: white; background: var(--mup-paste-accent);
  box-shadow: inset 0 1px 0 color-mix(in oklch, white 22%, transparent), 0 6px 14px -9px var(--mup-paste-accent);
  transition: background-color .15s, scale .3s var(--mup-paste-spring), opacity .2s;
  & svg { width: 15px; height: 15px; stroke-width: 2; transition: translate .4s var(--mup-paste-spring); }
  &:hover:not(:disabled) { background: color-mix(in oklch, black 12%, var(--mup-paste-accent)); }
  &:hover:not(:disabled) svg { translate: 2px 0; }
  &:active:not(:disabled) { scale: .95; }
  &:disabled { opacity: .4; cursor: not-allowed; box-shadow: none; }
}
.mup-paste[data-state="sending"] .mup-paste__send svg { animation: mup-paste-go .6s var(--mup-paste-ease) infinite; }
@keyframes mup-paste-go { 0% { translate: 0 0; opacity: 1; } 50% { translate: 8px 0; opacity: 0; } 51% { translate: -8px 0; opacity: 0; } 100% { translate: 0 0; opacity: 1; } }
.mup-paste[data-state="sending"] .mup-paste__box { opacity: .7; }

.mup-paste__try {
  grid-area: try; display: flex; flex-wrap: wrap; align-items: center; gap: 4px 6px; margin-top: 10px;
  font-size: 11.5px; color: var(--mup-paste-dim);
  & span { margin-right: 2px; }
  & button {
    height: 26px; padding: 0 9px; border-radius: 999px; font-size: 11.5px; font-weight: 600; color: var(--mup-paste-ink);
    background: var(--mup-paste-paper); box-shadow: inset 0 0 0 1px var(--mup-paste-line);
    transition: background-color .15s, box-shadow .15s, scale .3s var(--mup-paste-spring);
  }
  & button:hover { background: var(--mup-paste-tint); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--mup-paste-accent) 35%, transparent); }
  & button:active { scale: .95; }
  & button:disabled { opacity: .45; cursor: default; }
}
.mup-paste__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

@container (max-width: 320px) {
  .mup-paste__av { display: none; }
  .mup-paste__head { grid-template-columns: minmax(0, 1fr); }
  .mup-paste__hint { visibility: hidden; }
  .mup-paste__try span { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .mup-paste__chip, .mup-paste__sent, .mup-paste__fold, .mup-paste__send, .mup-paste__send svg, .mup-paste__icon, .mup-paste__try button { transition-duration: .01s; }
  .mup-paste__thumb { transition: none; }
  .mup-paste[data-flash] .mup-paste__box::after, .mup-paste[data-state="sending"] .mup-paste__send svg { animation: none; }
  .mup-paste__icon:hover { rotate: 0deg; }
}

