const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const later = (ms, fn) => setTimeout(() => { if (root.isConnected) fn(); }, ms);
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const EASE = 'cubic-bezier(.22,1,.36,1)';
const MAXB = 10e6, RATE = 150e3, FOLD_LINES = 12, FOLD_CHARS = 700;

const tray = $('.mup-paste__tray'), field = $('.mup-paste__field'), box = $('.mup-paste__box'), fileIn = $('.mup-paste__file');
const sendBtn = $('[data-act="send"]'), sendLbl = $('[data-send]'), hint = $('[data-hint]');
const foldText = $('[data-fold-text]'), inlineBtn = $('[data-act="inline"]'), sentText = $('[data-sent-text]'), live = $('.mup-paste__sr');
const samples = $$('[data-sample]');
$('[data-mod]').textContent = /Mac|iPhone|iPad/.test(navigator.platform || navigator.userAgent) ? '⌘' : 'Ctrl';
const HINT = hint.innerHTML;

let items = [], uid = 0, raf = 0, last = 0, onscreen = true, fold = null, foldT = 0, sentT = 0, state = 'idle';

const say = (m) => { live.textContent = ''; later(40, () => { live.textContent = m; }); };
const plural = (n, w) => n + ' ' + w + (n === 1 ? '' : 's');
const fmt = (b) => b < 1e3 ? Math.round(b) + ' B' : b < 1e6 ? (b / 1e3).toFixed(b < 1e4 ? 1 : 0) + ' KB' : (b / 1e6).toFixed(1) + ' MB';
const extOf = (n) => (n.includes('.') ? n.split('.').pop() : '').toLowerCase();
const two = (n) => String(n).padStart(2, '0');
const clock = (d = new Date()) => two(d.getHours()) + '.' + two(d.getMinutes()) + '.' + two(d.getSeconds());
const X = '<svg class="mup-paste__i" viewBox="0 0 24 24"><path d="M7 7l10 10M17 7 7 17"/></svg>';

function flash() {
  if (RM.matches) return;
  root.removeAttribute('data-flash');
  void root.offsetWidth;
  root.setAttribute('data-flash', '');
  later(950, () => root.removeAttribute('data-flash'));
}

/* ---------- chips ---------- */
function chip(it) {
  const li = document.createElement('li');
  li.className = 'mup-paste__chip';
  li.innerHTML =
    '<span class="mup-paste__thumb" aria-hidden="true">' +
      (it.kind === 'img' ? '<canvas width="80" height="80"></canvas>' : '<span class="mup-paste__doc">' + esc(it.tag) + (it.lines ? '<small>' + it.lines + ' ln</small>' : '') + '</span>') +
    '</span>' +
    '<span class="mup-paste__name" title="' + esc(it.name) + '">' + esc(it.name) + '</span>' +
    '<span class="mup-paste__meta"></span>' +
    '<button type="button" class="mup-paste__x">' + X + '</button>';
  it.el = li; it.meta = $('.mup-paste__meta', li); it.thumb = $('.mup-paste__thumb', li); it.x = $('.mup-paste__x', li);
  paint(it);
  return li;
}
function paint(it) {
  it.el.dataset.s = it.s;
  if (it.s === 'err') {
    it.meta.textContent = it.why;
    it.x.setAttribute('aria-label', 'Dismiss ' + it.name + ', ' + it.why);
    return;
  }
  const pct = it.s === 'done' ? 100 : Math.floor(it.p * 100);
  const step = it.s === 'done' ? 100 : Math.floor(pct / 5) * 5;
  if (step !== it.step) { it.step = step; it.thumb.style.setProperty('--mup-paste-a', (step * 3.6).toFixed(1) + 'deg'); }
  if (pct === it.pct && it.s === it.shown) return;
  it.pct = pct; it.shown = it.s;
  it.meta.textContent = it.s === 'done' ? (it.lines ? it.lines + ' lines · ' : '') + fmt(it.size) : fmt(it.p * it.size) + ' of ' + fmt(it.size) + ' · ' + pct + '%';
  it.x.setAttribute('aria-label', (it.s === 'done' ? 'Remove ' : 'Cancel upload of ') + it.name);
}

function attach(f, opts = {}) {
  const ext = extOf(f.name), type = f.type || '';
  const img = /^image\//.test(type), text = /^text\//.test(type) || /^(txt|log|csv|json|md)$/.test(ext), pdf = type === 'application/pdf' || ext === 'pdf';
  let why = '';
  if (/^video\//.test(type)) why = 'Videos aren’t supported here';
  else if (!img && !text && !pdf) why = (ext ? ext.toUpperCase() + ' files' : 'This type') + ' can’t be attached';
  else if (f.size > MAXB) why = fmt(f.size) + ' · limit is 10 MB';
  const name = img && /^image\.(png|jpe?g|gif|webp)$/i.test(f.name) ? 'Screenshot ' + clock().slice(0, 5) + '.' + ext : f.name;
  const it = {
    id: ++uid, name, size: f.size, p: 0, s: why ? 'err' : 'up', why, lines: opts.lines || 0,
    kind: img && !why ? 'img' : 'doc', tag: (ext || 'file').slice(0, 4).toUpperCase(),
    speed: f.size / Math.min(5, Math.max(1.2, f.size / RATE))
  };
  items.push(it);
  tray.append(chip(it));
  if (it.kind === 'img') {
    const cv = $('canvas', it.el);
    createImageBitmap(f).then((bmp) => {
      if (!root.isConnected) { bmp.close(); return; }
      const s = Math.max(80 / bmp.width, 80 / bmp.height), g = cv.getContext('2d');
      g.imageSmoothingQuality = 'high';
      g.drawImage(bmp, (80 - bmp.width * s) / 2, (80 - bmp.height * s) / 2, bmp.width * s, bmp.height * s);
      bmp.close();
    }).catch(() => {
      if (!root.isConnected || !items.includes(it)) return;
      it.s = 'err'; it.why = 'Couldn’t read this image'; paint(it); sync();
    });
  }
  tray.scrollTo({ left: tray.scrollWidth, behavior: RM.matches ? 'auto' : 'smooth' });
  kick();
  return it;
}

function removeItem(it, refocus) {
  const k = items.indexOf(it);
  if (k < 0) return;
  items.splice(k, 1);
  if (fold && fold.it === it) clearFold();
  const el = it.el, sibs = [...tray.children].filter((x) => x !== el);
  const finish = () => {
    const before = sibs.map((x) => x.getBoundingClientRect());
    el.remove();
    sync();
    if (!RM.matches) sibs.forEach((x, j) => {
      const r = x.getBoundingClientRect(), dx = before[j].left - r.left, dy = before[j].top - r.top;
      if (dx || dy) x.animate([{ transform: 'translate(' + dx + 'px,' + dy + 'px)' }, { transform: 'none' }], { duration: 380, easing: EASE });
    });
    if (refocus) { const n = items[Math.min(k, items.length - 1)]; (n ? n.x : field).focus(); }
  };
  if (RM.matches) { finish(); return; }
  el.setAttribute('data-out', '');
  el.style.pointerEvents = 'none';
  later(200, finish);
}

/* ---------- the paste itself: files first, then long text folds into a file ---------- */
function clearFold() {
  fold = null; clearTimeout(foldT);
  root.removeAttribute('data-fold');
  inlineBtn.tabIndex = -1;
}
function foldText_(text, start, end) {
  const lines = text.split(/\r\n|\r|\n/).length;
  const name = /^\s*[{[]/.test(text) ? 'pasted.json' : /\b(ERROR|WARN|INFO|DEBUG)\b/.test(text) ? 'pasted-log.txt' : 'pasted-text.txt';
  const f = new File([text], name, { type: 'text/plain' });
  const it = attach(f, { lines });
  clearFold();
  fold = { it, text, start, end };
  foldText.textContent = 'Folded ' + lines + ' lines into ' + name;
  root.setAttribute('data-fold', '');
  inlineBtn.tabIndex = 0;
  foldT = setTimeout(() => { if (root.isConnected && fold && fold.it === it) clearFold(); }, 9000);
  say('Long paste folded into ' + name + ', ' + lines + ' lines. Paste inline is available.');
}
function pasteText(text) {
  const start = field.selectionStart, end = field.selectionEnd;
  if (text.length > FOLD_CHARS || text.split(/\r\n|\r|\n/).length > FOLD_LINES) { foldText_(text, start, end); flash(); sync(); return true; }
  return false;
}
function pasteFiles(files) {
  const added = files.map((f) => attach(f));
  flash();
  sync();
  const ok = added.filter((it) => it.s !== 'err'), bad = added.filter((it) => it.s === 'err');
  say((ok.length ? plural(ok.length, 'file') + ' attached: ' + ok.map((it) => it.name).join(', ') + '.' : '') + bad.map((it) => ' ' + it.name + ': ' + it.why + '.').join(''));
}
field.addEventListener('paste', (e) => {
  const dt = e.clipboardData;
  if (!dt || state === 'sending') return;
  const files = [...dt.items].filter((x) => x.kind === 'file').map((x) => x.getAsFile()).filter(Boolean);
  if (files.length) { e.preventDefault(); pasteFiles(files); return; }
  const text = dt.getData('text/plain');
  if (text && pasteText(text)) e.preventDefault();
});
inlineBtn.addEventListener('click', () => {
  if (!fold) return;
  const { it, text, start, end } = fold;
  clearFold();
  removeItem(it, false);
  field.focus();
  const a = Math.min(start, field.value.length), b = Math.min(end, field.value.length);
  const pre = a > 0 && !/\s/.test(field.value[a - 1]) ? '\n' : '';
  field.setRangeText(pre + text, a, b, 'end');
  sync();
  say('Pasted inline instead.');
});

/* ---------- sending ---------- */
function sync() {
  const up = items.filter((it) => it.s === 'up').length, bad = items.filter((it) => it.s === 'err').length, ok = items.length - up - bad;
  const text = field.value.trim().length > 0;
  sendBtn.disabled = state === 'sending' || !!up || !!bad || (!text && !ok);
  sendLbl.textContent = state === 'sending' ? 'Sending' : 'Send';
  hint.innerHTML = up ? 'Uploading ' + plural(up, 'file') + '…' : bad ? '<b>Remove ' + plural(bad, 'file') + '</b> to send' : HINT;
  root.dataset.state = state;
  samples.forEach((b) => { b.disabled = state === 'sending'; });
}
field.addEventListener('input', sync);
function send() {
  if (sendBtn.disabled) return;
  state = 'sending';
  clearFold();
  sync();
  later(RM.matches ? 300 : 750, () => {
    const n = items.length, words = field.value.trim().split(/\s+/).filter(Boolean).length;
    const d = new Date();
    if (!RM.matches) items.forEach((it, i) => it.el.animate([{ opacity: 1, transform: 'none', filter: 'blur(0)' }, { opacity: 0, transform: 'translateY(-10px) scale(.94)', filter: 'blur(3px)' }], { duration: 260, delay: i * 45, easing: EASE, fill: 'forwards' }));
    later(RM.matches ? 0 : 260 + n * 45, () => {
      items = [];
      tray.replaceChildren();
      field.value = '';
      state = 'idle';
      sentText.textContent = 'Sent to Maren at ' + two(d.getHours()) + ':' + two(d.getMinutes()) + (n ? ' · ' + plural(n, 'attachment') : '');
      root.setAttribute('data-sent', '');
      clearTimeout(sentT);
      sentT = setTimeout(() => { if (root.isConnected) root.removeAttribute('data-sent'); }, 5000);
      sync();
      field.focus();
      say('Reply sent' + (words ? ', ' + plural(words, 'word') : '') + (n ? ', ' + plural(n, 'attachment') : '') + '.');
    });
  });
}
sendBtn.addEventListener('click', send);

/* ---------- keyboard: Cmd/Ctrl+Enter sends, Backspace at the start walks into the chips ---------- */
field.addEventListener('keydown', (e) => {
  if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) { e.preventDefault(); send(); return; }
  if (e.key === 'Backspace' && field.selectionStart === 0 && field.selectionEnd === 0 && items.length) { e.preventDefault(); items[items.length - 1].x.focus(); }
  if (e.key === 'Escape' && fold) { e.preventDefault(); clearFold(); }
});
tray.addEventListener('keydown', (e) => {
  const xs = items.map((it) => it.x), k = xs.indexOf(document.activeElement);
  if (k < 0) return;
  if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') { e.preventDefault(); (xs[k - 1] || xs[0]).focus(); }
  else if (e.key === 'ArrowRight' || e.key === 'ArrowDown') { e.preventDefault(); (xs[k + 1] || field).focus(); }
  else if (e.key === 'Delete' || e.key === 'Backspace') { e.preventDefault(); const it = items[k]; removeItem(it, true); say('Removed ' + it.name + '.'); }
  else if (e.key === 'Escape') { e.preventDefault(); field.focus(); }
});
tray.addEventListener('click', (e) => {
  const b = e.target.closest('.mup-paste__x');
  if (!b) return;
  const it = items.find((x) => x.x === b);
  if (!it) return;
  removeItem(it, e.detail === 0);
  say((it.s === 'up' ? 'Upload cancelled: ' : 'Removed ') + it.name + '.');
});

$('[data-act="attach"]').addEventListener('click', () => fileIn.click());
fileIn.addEventListener('change', () => { if (fileIn.files.length) pasteFiles([...fileIn.files]); fileIn.value = ''; field.focus(); });

let depth = 0;
const hasFiles = (e) => !!e.dataTransfer && [...e.dataTransfer.types].includes('Files');
root.addEventListener('dragenter', (e) => { if (!hasFiles(e)) return; e.preventDefault(); if (++depth === 1) root.setAttribute('data-over', ''); });
root.addEventListener('dragover', (e) => { if (!hasFiles(e)) return; e.preventDefault(); e.dataTransfer.dropEffect = 'copy'; });
root.addEventListener('dragleave', (e) => { if (!hasFiles(e)) return; if (--depth <= 0) { depth = 0; root.removeAttribute('data-over'); } });
root.addEventListener('drop', (e) => {
  if (!hasFiles(e)) return;
  e.preventDefault(); depth = 0; root.removeAttribute('data-over');
  if (state !== 'sending') pasteFiles([...e.dataTransfer.files]);
});

/* ---------- simulated upload ---------- */
function tick(t) {
  if (!root.isConnected) { io.disconnect(); return; }
  raf = 0;
  const dt = Math.min(0.1, (t - last) / 1000);
  last = t;
  let any = false, ended = false;
  for (const it of items) {
    if (it.s !== 'up') continue;
    it.p = Math.min(1, it.p + (dt * it.speed * (0.75 + 0.5 * Math.abs(Math.sin(t / 360 + it.id)))) / it.size);
    if (it.p >= 1) { it.s = 'done'; ended = true; say(it.name + ' uploaded.'); } else any = true;
    paint(it);
  }
  if (ended) sync();
  if (any && onscreen) raf = requestAnimationFrame(tick);
}
function kick() {
  if (raf || !onscreen || !items.some((it) => it.s === 'up')) return;
  last = performance.now();
  raf = requestAnimationFrame(tick);
}

/* ---------- samples: the same paths a real clipboard takes ---------- */
function rr(g, x, y, w, h, r, fill) { g.beginPath(); g.roundRect(x, y, w, h, r); g.fillStyle = fill; g.fill(); }
function screenshot() {
  const c = document.createElement('canvas');
  c.width = 960; c.height = 600;
  const g = c.getContext('2d');
  g.fillStyle = '#e9edf3'; g.fillRect(0, 0, 960, 600);
  rr(g, 36, 28, 888, 548, 14, '#ffffff');
  rr(g, 36, 28, 888, 42, 14, '#f1f3f7'); g.fillStyle = '#f1f3f7'; g.fillRect(36, 56, 888, 14);
  ['#c9ced8', '#c9ced8', '#c9ced8'].forEach((col, i) => { g.beginPath(); g.arc(60 + i * 18, 49, 6, 0, 7); g.fillStyle = col; g.fill(); });
  g.fillStyle = '#f6f7fa'; g.fillRect(36, 70, 168, 506);
  for (let i = 0; i < 7; i++) rr(g, 54, 92 + i * 34, i === 2 ? 120 : 96 + (i * 13) % 40, 12, 6, i === 2 ? '#c8d4f2' : '#e1e5ec');
  const notes = ['#ffe38a', '#bfe3c9', '#f8c4b4', '#c9d7f7', '#ffe38a', '#e4d2f2'];
  for (let i = 0; i < 12; i++) rr(g, 232 + (i % 4) * 166, 96 + Math.floor(i / 4) * 150, 148, 128, 8, notes[i % notes.length]);
  g.fillStyle = 'rgba(28,34,48,.46)'; g.fillRect(204, 70, 720, 506);
  rr(g, 340, 214, 448, 186, 14, '#ffffff');
  g.fillStyle = '#1d2433'; g.font = '600 22px system-ui, sans-serif'; g.fillText('Exporting “Q4 roadmap”', 372, 262);
  g.fillStyle = '#6b7385'; g.font = '16px system-ui, sans-serif'; g.fillText('Rendering frame 1,271 of 1,284', 372, 292);
  rr(g, 372, 318, 384, 12, 6, '#e6e9f0'); rr(g, 372, 318, 380, 12, 6, '#3b63d1');
  g.fillStyle = '#1d2433'; g.font = '600 16px ui-monospace, Menlo, monospace'; g.fillText('99%', 372, 366);
  rr(g, 664, 346, 92, 32, 8, '#eef1f6'); g.fillStyle = '#3d4658'; g.font = '600 15px system-ui, sans-serif'; g.fillText('Cancel', 685, 368);
  return c;
}
function serverLog() {
  const out = [], t0 = Date.UTC(2026, 9, 2, 14, 31, 7, 412);
  const at = (ms) => new Date(t0 + ms).toISOString();
  out.push(at(0) + ' INFO  export-worker[7] job=exp_8812 board=b_44120 started, 1,284 frames');
  for (let i = 1; i <= 60; i++) {
    const f = Math.round((i / 60) * 1271), ms = 380 + ((i * 7919) % 900);
    out.push(at(i * 1520) + (ms > 1100 ? ' WARN ' : ' INFO ') + ' export-worker[7] frame ' + f + '/1284 rendered in ' + ms + ' ms, heap ' + (1.2 + i * 0.046).toFixed(2) + ' GB');
  }
  out.push(at(93400) + ' WARN  export-worker[7] frame 1271/1284 render took 4,812 ms');
  out.push(at(121700) + ' ERROR export-worker[7] job=exp_8812 stalled at 99%, rasterizer out of memory (heap 3.98 of 4.00 GB)');
  out.push(at(121702) + ' INFO  export-queue job=exp_8812 marked retryable, attempt 1 of 3');
  return out.join('\n');
}
samples.forEach((b) => b.addEventListener('click', () => {
  if (state === 'sending') return;
  field.focus();
  const kind = b.dataset.sample;
  if (kind === 'shot') screenshot().toBlob((blob) => { if (root.isConnected && blob) pasteFiles([new File([blob], 'image.png', { type: 'image/png' })]); }, 'image/png');
  else if (kind === 'log') pasteText(serverLog());
  else pasteFiles([{ name: 'export-repro.mov', size: 24.6e6, type: 'video/quicktime' }]);
}));

const io = new IntersectionObserver((es) => {
  if (!root.isConnected) { io.disconnect(); return; }
  onscreen = es[es.length - 1].isIntersecting;
  if (onscreen) kick();
});
io.observe(root);
field.value = 'Hi Maren, I can reproduce the stall on boards over 1,200 frames. Here is what our side shows:';
screenshot().toBlob((blob) => { if (root.isConnected && blob) { attach(new File([blob], 'image.png', { type: 'image/png' })); sync(); } }, 'image/png');
sync();

