@property --mup-csv-reveal {
  syntax: "<percentage>";
  inherits: false;
  initial-value: 0%;
}

/* Re-theme with --mup-csv-bg, -ink, -accent (the highlighter) and -danger. */
.mup-csv {
  --mup-csv-bg: oklch(0.978 0.011 92);
  --mup-csv-ink: oklch(0.22 0.012 80);
  --mup-csv-accent: oklch(0.9 0.16 102);
  --mup-csv-danger: oklch(0.55 0.19 27);

  --mup-csv-dim: color-mix(in oklab, var(--mup-csv-ink) 58%, var(--mup-csv-bg));
  --mup-csv-faint: color-mix(in oklab, var(--mup-csv-ink) 32%, var(--mup-csv-bg));
  --mup-csv-line: color-mix(in oklab, var(--mup-csv-ink) 12%, var(--mup-csv-bg));
  --mup-csv-paper: color-mix(in oklab, white 70%, var(--mup-csv-bg));
  --mup-csv-warn: oklch(0.6 0.14 62);
  --mup-csv-mark: color-mix(in oklab, var(--mup-csv-accent) 85%, transparent);
  --mup-csv-ease: cubic-bezier(.22, 1, .36, 1);
  --mup-csv-spring: linear(0, 0.034 2.3%, 0.13 4.7%, 0.484 11.6%, 0.656 15.5%, 0.786 19.5%, 0.883 23.6%, 0.951 27.9%, 1.006 33.3%, 1.03 38.5%, 1.037 44.2%, 1.025 54.1%, 1.008 66.8%, 1);

  container-type: inline-size;
  position: relative;
  display: block;
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  padding: 14px;
  border-radius: 16px;
  background: var(--mup-csv-bg);
  color: var(--mup-csv-ink);
  box-shadow: 0 0 0 1px var(--mup-csv-line), 0 18px 40px -30px color-mix(in oklab, var(--mup-csv-ink) 70%, transparent);
  font: 400 13px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-align: left;
  accent-color: var(--mup-csv-ink);
}
@supports not (transition-timing-function: linear(0, 1)) {
  .mup-csv { --mup-csv-spring: cubic-bezier(.3, 1.35, .5, 1); }
}
:where(.mup-csv) *, :where(.mup-csv) *::before, :where(.mup-csv) *::after { box-sizing: border-box; }
:where(.mup-csv) :is(p, h3, ol, li, dl, dt, dd) { margin: 0; padding: 0; list-style: none; }
:where(.mup-csv) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
:where(.mup-csv) :focus-visible { outline: 2px solid var(--mup-csv-ink); outline-offset: 2px; }
.mup-csv .mup-csv__i { fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }

/* the wrapper carries the grid, so the root's own container query can re-flow it */
.mup-csv__wrap { display: grid; grid-template-areas: "head" "map" "pv" "foot"; grid-template-columns: minmax(0, 1fr); }

/* ---------- header ---------- */
.mup-csv__head {
  grid-area: head; display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "eye btn" "title btn" "file file";
  column-gap: 10px; margin-bottom: 10px;
  & h3 { grid-area: title; font-size: clamp(15px, 5cqi, 18px); font-weight: 750; letter-spacing: -.02em; line-height: 1.15; text-wrap: balance; }
  & .mup-csv__ghost { grid-area: btn; align-self: center; }
}
.mup-csv__eyebrow {
  grid-area: eye; font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--mup-csv-dim);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; margin-bottom: 3px;
}
.mup-csv__file {
  grid-area: file; display: flex; align-items: center; gap: 6px; margin-top: 8px; min-width: 0;
  font-size: 12px; color: var(--mup-csv-dim);
  & svg { width: 16px; height: 16px; color: var(--mup-csv-ink); }
  & p { min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }
  & b { font: 600 12px/1.3 ui-monospace, Menlo, monospace; color: var(--mup-csv-ink); letter-spacing: -.01em; }
}
.mup-csv__ghost {
  height: 28px; padding: 0 10px; border-radius: 7px; font-size: 12px; font-weight: 600; white-space: nowrap;
  background: var(--mup-csv-paper); box-shadow: inset 0 0 0 1px var(--mup-csv-line);
  transition: background-color .15s, scale .3s var(--mup-csv-spring);
  &:hover:not(:disabled) { background: color-mix(in oklab, var(--mup-csv-ink) 5%, var(--mup-csv-paper)); }
  &:active:not(:disabled) { scale: .95; }
  &:disabled { opacity: .45; cursor: default; }
}

/* ---------- mapping rows share one column template through subgrid ---------- */
.mup-csv__map {
  grid-area: map; display: grid; grid-template-columns: minmax(0, 1fr) 14px minmax(0, 1.12fr); column-gap: 8px;
  align-content: start; max-height: 176px; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin;
  border-top: 1.5px solid var(--mup-csv-ink); border-bottom: 1px solid var(--mup-csv-line);
}
.mup-csv__cols, .mup-csv__row { grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; }
.mup-csv__cols {
  position: sticky; top: 0; z-index: 2; padding: 6px 0 5px; background: var(--mup-csv-bg);
  font-size: 9.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--mup-csv-dim);
}
.mup-csv__row {
  grid-template-areas: "src arrow sel" "src arrow note"; align-items: center; row-gap: 2px;
  padding: 7px 0; border-top: 1px solid var(--mup-csv-line);
}
.mup-csv__src {
  grid-area: src; display: grid; gap: 2px; min-width: 0;
  & b {
    justify-self: start; max-width: 100%; padding: 0 2px; margin-left: -2px;
    font: 650 12px/1.35 ui-monospace, Menlo, monospace; letter-spacing: -.02em;
    white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
    /* the highlighter stroke: a gradient whose width is a registered percentage */
    background: linear-gradient(100deg, transparent 0 2px, var(--mup-csv-mark) 4px calc(100% - 3px), transparent 100%) 0 88% / var(--mup-csv-reveal) 52% no-repeat;
    transition: --mup-csv-reveal .5s var(--mup-csv-ease), color .2s;
    transition-delay: calc(var(--i, 0) * 80ms);
  }
  & small { font-size: 11px; color: var(--mup-csv-dim); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
