/* ---------- 312 rows from a seeded generator; the 7 bad emails are derived from their own row ---------- */
function rng(seed) { let s = seed >>> 0; return () => (s = (Math.imul(s, 1664525) + 1013904223) >>> 0) / 4294967296; }
const FIRST = ['Ada', 'Bruno', 'Chiara', 'Dmitri', 'Esme', 'Farid', 'Greta', 'Hiro', 'Imani', 'Jonas', 'Keira', 'Luca', 'Maren', 'Nadia', 'Oskar', 'Priya', 'Quinn', 'Rafael', 'Saoirse', 'Tomas', 'Uma', 'Viktor', 'Wen', 'Yara', 'Zeki'];
