const COS = [['Copperleaf Energy', 'copperleaf.io'], ['Brisk Freight', 'briskfreight.com'], ['Tallis Dairy', 'tallisdairy.co'], ['Quarry Lane Studio', 'quarrylane.studio'], ['Meridel Health', 'meridel.health'], ['Sundial Robotics', 'sundial.dev'], ['Halden & Rowe', 'haldenrowe.com'], ['Kestrel Maps', 'kestrelmaps.app'], ['Orchard Ledger', 'orchardledger.com'], ['Pallas Bio', 'pallasbio.eu']];
