const NOTES = ['Wants pricing for 40 seats', 'Follow up after Q4 planning', 'Met at the demo bar', 'Asked about SSO', 'Send the logistics case study', '', '', 'Has an RFP in November', 'Intro from the Kestrel team', ''];
const BAD = {
