}

const T = { full: 'Full name (split)', first: 'First name', last: 'Last name', email: 'Email', phone: 'Phone', company: 'Company', title: 'Job title', country: 'Country' };
const OPTS = '<option value="">Don’t import</option><optgroup label="Person"><option value="full">Full name (split)</option><option value="first">First name *</option><option value="last">Last name</option><option value="email">Email *</option><option value="phone">Phone</option></optgroup><optgroup label="Organisation"><option value="company">Company</option><option value="title">Job title</option><option value="country">Country</option></optgroup>';
