  ['first', /^(first ?name|given ?name|forename)$/i, 'auto'], ['last', /^(last ?name|surname|family ?name)$/i, 'auto'],
  ['full', /^(full ?name|name|contact ?name)$/i, 'auto'], ['email', /e-?mail/i, 'auto'], ['phone', /(phone|mobile|tel\b)/i, 'auto'],
  ['company', /(company|organi[sz]ation|employer)/i, 'auto'], ['title', /^(job ?title|title)$/i, 'auto'], ['title', /(role|position)/i, 'low'],
  ['country', /(country|nation)/i, 'auto']
