    row.innerHTML = '<span class="mup-csv__src"><b title="' + esc(h) + '">' + esc(h || 'Column ' + (c + 1)) + '</b><small>' + esc(ex) + '</small></span>' + ARROW +
      '<label class="mup-csv__sel"><select aria-label="Map ' + esc(h || 'column ' + (c + 1)) + ' to">' + OPTS + '</select>' + CHEV + '</label>' +
