function automap() {
  const used = new Set();
  data.head.forEach((h, c) => {
    const g = GUESS.find(([t, re]) => re.test(h.trim()) && !used.has(t) && !(t === 'full' && (used.has('first') || used.has('last'))) && !((t === 'first' || t === 'last') && used.has('full')));
