    if (clash != null) { dup[c] = clash; return; }
    owner[key] = c;
    if (t === 'full') { owner.full = c; owner.last = c; }
  });
  const errs = [];
  if (owner.email == null) errs.push('Map a column to Email');
  if (owner.first == null) errs.push('Map a column to First name');
  const record = (i) => {
    const row = data.rows[i], o = {};
