    row.toggleAttribute('data-mapped', !!t);
    let tone = '', txt;
    const vals = data.rows.map((r) => (r[c] || '').trim()), filled = vals.filter(Boolean).length, empty = vals.length - filled;
    if (!t) { txt = 'Not imported'; tone = 'off'; }
    else if (A.dup[c] != null) { txt = T[t] + ' already comes from “' + data.head[A.dup[c]] + '”'; tone = 'err'; }
    else if (t === 'email') {
      const bad = vals.filter((v) => !EMAIL.test(v)).length;
      txt = bad ? n0(bad) + ' invalid · rows skipped' : n0(filled) + ' valid addresses';
      tone = bad ? 'warn' : '';
    } else if (t === 'full') txt = n0(filled) + ' names, split in two';
    else txt = n0(filled) + ' values' + (empty ? ' · ' + n0(empty) + ' empty' : '');
    row.dataset.tone = tone;
    note.innerHTML = (conf[c] === 'auto' ? '<i>Auto</i>' : conf[c] === 'low' ? '<i data-low>Check</i>' : '') + '<span>' + esc(txt) + '</span>';
  });
  const ok = A.nw + A.up;
  bar.new.style.setProperty('--mup-csv-w', A.errs.length ? 0 : A.nw);
  bar.upd.style.setProperty('--mup-csv-w', A.errs.length ? 0 : A.up);
  bar.skip.style.setProperty('--mup-csv-w', A.errs.length ? 0 : A.skip.length);
  if (state === 'matching') sumEl.textContent = 'Matching columns…';
  else if (state === 'review') sumEl.innerHTML = '<b>' + n0(ok) + '</b> imported · <em>' + n0(A.skip.length) + ' skipped</em> · fix them in the file';
  else if (A.errs.length) sumEl.innerHTML = '<em>' + A.errs.join(' and ') + '</em>';
  else sumEl.innerHTML = '<b>' + n0(A.nw) + '</b> new · <b>' + n0(A.up) + '</b> update · ' + (A.skip.length ? '<em>' + n0(A.skip.length) + ' skipped</em>' : 'none skipped');
  impBtn.disabled = state === 'review' ? false : state !== 'ready' || !!A.errs.length || !ok;
  if (state !== 'importing') impLbl.textContent = state === 'review' ? 'Start over' : A.errs.length || !ok ? 'Import' : 'Import ' + n0(ok);
  issueBtn.hidden = !A.skip.length || !!A.errs.length;
  issueBtn.textContent = plural(A.skip.length, 'issue');
  root.dataset.state = state;
  show(0);
}

function show(dir) {
  const n = data.rows.length;
  rec = Math.max(0, Math.min(n - 1, rec));
  recLbl.textContent = n0(rec + 1) + ' of ' + n0(n);
  recLbl.parentElement.setAttribute('aria-label', 'Preview, record ' + n0(rec + 1) + ' of ' + n0(n) + ', line ' + n0(rec + 2));
  prevBtn.disabled = rec === 0; nextBtn.disabled = rec === n - 1;
  const o = A.record(rec), v = A.errs.length ? '' : A.verdict(o);
  const owned = new Set(mapping.filter((t, c) => t && A.dup[c] == null).flatMap((t) => (t === 'full' ? ['first', 'last'] : [t])));
  recBox.innerHTML = FIELDS.map(([k, label, wide]) => {
    const on = owned.has(k), val = on ? o[k] || '' : 'Not mapped';
    const bad = k === 'email' && on && v.startsWith(val ? 'invalid' : 'no email');
    return '<div' + (wide ? ' data-wide' : '') + '><dt>' + label + '</dt><dd' + (!on ? ' data-off' : bad ? ' data-bad' : '') + '>' + esc(val) + '</dd></div>';
  }).join('');
  whyEl.textContent = A.errs.length ? '' : v ? 'Line ' + n0(rec + 2) + ' will be skipped: ' + v + '.' : '';
  if (dir && !RM.matches) {
    recBox.style.setProperty('--mup-csv-dx', dir > 0 ? '8px' : '-8px');
    recBox.removeAttribute('data-turn'); void recBox.offsetWidth; recBox.setAttribute('data-turn', '');
  }
}

/* ---------- events ---------- */
map.addEventListener('change', (e) => {
  const sel = e.target.closest('select');
  if (!sel) return;
  const c = rowsEl.findIndex((r) => r.contains(sel));
  mapping[c] = sel.value; conf[c] = '';
  refresh();
  const t = sel.value;
  say((t ? data.head[c] + ' mapped to ' + T[t] + '. ' : data.head[c] + ' will not be imported. ') +
    (A.errs.length ? A.errs.join('. ') + '.' : n0(A.nw + A.up) + ' contacts ready, ' + n0(A.skip.length) + ' skipped.'));
});
prevBtn.addEventListener('click', () => { rec--; show(-1); });
nextBtn.addEventListener('click', () => { rec++; show(1); });
issueBtn.addEventListener('click', () => {
  if (!A.skip.length) return;
  const nx = A.skip.find((i) => i > rec);
  const to = nx != null ? nx : A.skip[0];
  const d = to > rec ? 1 : -1;
  rec = to; show(d);
  say('Line ' + n0(rec + 2) + ': ' + whyEl.textContent);
});
pv.addEventListener('keydown', (e) => {
  if (e.key === 'ArrowLeft' && rec > 0) { e.preventDefault(); rec--; show(-1); }
  else if (e.key === 'ArrowRight' && rec < data.rows.length - 1) { e.preventDefault(); rec++; show(1); }
});

function start(d, announce) {
  cancelAnimationFrame(impRaf);
  data = d; rec = 0; state = 'matching';
  build();
  refresh();
  later(RM.matches ? 50 : 380, () => {
    automap();
    refresh();
    later(RM.matches ? 50 : 300 + data.head.length * 80, () => {
      state = 'ready';
      refresh();
      if (announce) say(data.name + ': ' + plural(data.rows.length, 'row') + '. ' + mapping.filter(Boolean).length + ' of ' + data.head.length + ' columns matched automatically.');
    });
  });
}
async function load(f) {
  if (!f) return;
  if (!/\.(csv|txt)$/i.test(f.name) && !/csv|text\/plain/.test(f.type)) { sumEl.innerHTML = '<em>“' + esc(f.name) + '” isn’t a CSV file</em>'; say(f.name + ' is not a CSV file.'); return; }
  if (f.size > 5e6) { sumEl.innerHTML = '<em>' + (f.size / 1e6).toFixed(1) + ' MB · the limit is 5 MB</em>'; say('That file is over 5 megabytes.'); return; }
  try {
    const rows = parse(await f.text());
    if (!root.isConnected) return;
    if (rows.length < 2) throw new Error('empty');
    const head = rows[0].slice(0, 12).map((h) => h.trim());
    start({ name: f.name, head, rows: rows.slice(1, 5001).map((r) => head.map((_, c) => r[c] || '')), existing: new Set() }, true);
  } catch (err) {
    sumEl.innerHTML = '<em>Couldn’t read rows from “' + esc(f.name) + '”</em>';
    say('Could not read rows from ' + f.name + '.');
  }
}
$('[data-act="choose"]').addEventListener('click', () => input.click());
input.addEventListener('change', () => { load(input.files[0]); input.value = ''; });
root.addEventListener('dragover', (e) => { if (e.dataTransfer && [...e.dataTransfer.types].includes('Files')) { e.preventDefault(); e.dataTransfer.dropEffect = 'copy'; } });
root.addEventListener('drop', (e) => { if (!e.dataTransfer || !e.dataTransfer.files.length) return; e.preventDefault(); if (state !== 'importing') load(e.dataTransfer.files[0]); });

/* ---------- import: count through the rows, then open the receipt from the button ---------- */
impBtn.addEventListener('click', () => {
  if (impBtn.disabled) return;
  if (state === 'review') { start(sample(), true); return; }
  const total = A.nw + A.up, rows = data.rows.length, skipSet = new Set(A.skip), t0 = performance.now(), dur = RM.matches ? 400 : 1700;
  state = 'importing';
  refresh();
  let shown = -1;
  const step = (t) => {
    if (!root.isConnected) return;
    const p = Math.min(1, (t - t0) / dur), upto = Math.floor(p * rows);
    let k = 0;
    for (let i = 0; i < upto; i++) if (!skipSet.has(i)) k++;
    if (k !== shown) { shown = k; impLbl.textContent = n0(k) + ' / ' + n0(total); }
    bar.new.parentElement.style.setProperty('--mup-csv-p', (p * 100).toFixed(1) + '%');
    if (p < 1) { impRaf = requestAnimationFrame(step); return; }
    const b = impBtn.getBoundingClientRect(), d = done.getBoundingClientRect();
    done.style.setProperty('--mup-csv-ox', (b.left + b.width / 2 - d.left).toFixed(0) + 'px');
    done.style.setProperty('--mup-csv-oy', (b.top + b.height / 2 - d.top).toFixed(0) + 'px');
    doneBig.textContent = plural(total, 'contact') + ' imported';
    doneSub.textContent = n0(A.nw) + ' new · ' + n0(A.up) + ' updated · ' + n0(A.skip.length) + ' skipped';
    skippedBtn.textContent = A.skip.length ? 'Review ' + n0(A.skip.length) + ' skipped' : 'View contacts';
    state = 'done';
    root.dataset.state = state;
    done.setAttribute('aria-hidden', 'false');
    skippedBtn.tabIndex = 0; undoBtn.tabIndex = 0;
    later(RM.matches ? 0 : 450, () => skippedBtn.focus());
    say(doneBig.textContent + '. ' + doneSub.textContent + '.');
  };
  impRaf = requestAnimationFrame(step);
});
function closeDone() {
  done.setAttribute('aria-hidden', 'true');
  skippedBtn.tabIndex = -1; undoBtn.tabIndex = -1;
}
skippedBtn.addEventListener('click', () => {
  closeDone();
  state = 'review';
  refresh();
  if (A.skip.length) { rec = A.skip[0]; show(1); issueBtn.focus(); }
  else prevBtn.focus();
  say(A.skip.length ? 'Showing skipped rows. ' + whyEl.textContent : 'All rows were imported.');
});
undoBtn.addEventListener('click', () => {
  closeDone();
  state = 'ready';
  refresh();
  impBtn.focus();
  say('Import undone. Nothing was added to Fernhill.');
});
root.addEventListener('keydown', (e) => { if (e.key === 'Escape' && state === 'done') { e.preventDefault(); skippedBtn.click(); } });

start(data, false);

