/* Re-theme with --mup-resume-bg, -ink, -accent and -danger. */
.mup-resume {
  --mup-resume-bg: oklch(0.215 0.024 222);
  --mup-resume-ink: oklch(0.95 0.012 210);
  --mup-resume-accent: oklch(0.81 0.145 76);
  --mup-resume-danger: oklch(0.68 0.17 28);

  --mup-resume-dim: color-mix(in oklab, var(--mup-resume-ink) 58%, var(--mup-resume-bg));
  --mup-resume-faint: color-mix(in oklab, var(--mup-resume-ink) 30%, var(--mup-resume-bg));
  --mup-resume-line: color-mix(in oklab, var(--mup-resume-ink) 11%, transparent);
  --mup-resume-well: color-mix(in oklab, black 22%, var(--mup-resume-bg));
  --mup-resume-cell: color-mix(in oklab, var(--mup-resume-ink) 9%, var(--mup-resume-well));
  --mup-resume-done: color-mix(in oklab, var(--mup-resume-accent) 62%, var(--mup-resume-well));
  --mup-resume-ease: cubic-bezier(.22, 1, .36, 1);
  --mup-resume-spring: linear(0, 0.034 2.3%, 0.13 4.7%, 0.484 11.6%, 0.656 15.5%, 0.786 19.5%, 0.883 23.6%, 0.951 27.9%, 1.006 33.3%, 1.03 38.5%, 1.037 44.2%, 1.025 54.1%, 1.008 66.8%, 1);
  --mup-resume-cols: 24;

  container-type: inline-size;
  position: relative;
  display: grid;
  grid-template-areas: "head" "meta" "grid" "legend" "spark" "foot";
  grid-template-columns: minmax(0, 1fr);
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  padding: 14px;
  border-radius: 18px;
  overflow: hidden;
  background: var(--mup-resume-bg);
  color: var(--mup-resume-ink);
  box-shadow: inset 0 1px 0 color-mix(in oklab, var(--mup-resume-ink) 8%, transparent), 0 0 0 1px color-mix(in oklab, black 45%, transparent);
  font: 400 13px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-align: left;
}
@supports not (transition-timing-function: linear(0, 1)) {
  .mup-resume { --mup-resume-spring: cubic-bezier(.3, 1.35, .5, 1); }
}
:where(.mup-resume) *, :where(.mup-resume) *::before, :where(.mup-resume) *::after { box-sizing: border-box; }
:where(.mup-resume) :is(p, h3, ul, li) { margin: 0; padding: 0; list-style: none; }
:where(.mup-resume) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
:where(.mup-resume) :focus-visible { outline: 2px solid var(--mup-resume-accent); outline-offset: 2px; }
.mup-resume .mup-resume__i { fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }

.mup-resume__head {
  grid-area: head; display: flex; align-items: end; justify-content: space-between; gap: 12px;
  & div { min-width: 0; }
  & h3 {
    font: 650 clamp(13px, 4.2cqi, 15px)/1.25 ui-monospace, Menlo, monospace; letter-spacing: -.02em;
    white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  }
}
.mup-resume__eyebrow {
  font-size: 10.5px; font-weight: 650; letter-spacing: .1em; text-transform: uppercase; color: var(--mup-resume-dim);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; margin-bottom: 3px;
}
.mup-resume__pct {
  display: flex; align-items: baseline; flex: none; color: var(--mup-resume-accent);
  font: 700 clamp(28px, 11cqi, 40px)/.85 ui-monospace, Menlo, monospace; letter-spacing: -.05em; font-variant-numeric: tabular-nums;
  & span { font-size: .45em; margin-left: 2px; letter-spacing: 0; color: var(--mup-resume-dim); }
}
.mup-resume[data-state="cancelled"] .mup-resume__pct { color: var(--mup-resume-faint); }
.mup-resume__meta {
  grid-area: meta; margin-top: 6px; font: 500 11.5px/1.3 ui-monospace, Menlo, monospace; color: var(--mup-resume-dim);
  font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  & b { color: var(--mup-resume-ink); font-weight: 650; }
}

/* ---------- 240 chunks, one cell each ---------- */
.mup-resume__grid {
  grid-area: grid; display: grid; grid-template-columns: repeat(var(--mup-resume-cols), minmax(0, 1fr)); gap: 2px;
  margin-top: 12px; padding: 6px; border-radius: 10px; background: var(--mup-resume-well);
  box-shadow: inset 0 1px 3px color-mix(in oklab, black 40%, transparent);
  & i {
    aspect-ratio: 1; border-radius: 2px; background: var(--mup-resume-cell);
    transition: background-color .45s var(--mup-resume-ease), scale .4s var(--mup-resume-spring), box-shadow .3s;
  }
  & i[data-s="ok"] { background: var(--mup-resume-done); }
  & i[data-s="fly"] {
    background: linear-gradient(to top, var(--mup-resume-accent) calc(var(--mup-resume-p, 0) * 100%), color-mix(in oklab, var(--mup-resume-accent) 22%, var(--mup-resume-well)) 0);
    box-shadow: 0 0 0 1px var(--mup-resume-accent), 0 0 10px -1px var(--mup-resume-accent);
    scale: 1.18; z-index: 1; transition-duration: .15s;
  }
  & i[data-s="err"] { background: var(--mup-resume-danger); scale: .7; transition-duration: .12s; }
}
.mup-resume[data-state="paused"] .mup-resume__grid i[data-s="ok"] { background: color-mix(in oklab, var(--mup-resume-accent) 42%, var(--mup-resume-well)); }
.mup-resume[data-state="verify"] .mup-resume__grid i, .mup-resume[data-state="done"] .mup-resume__grid i {
  animation: mup-resume-wave .9s var(--mup-resume-ease) both;
  animation-delay: calc((var(--x) + var(--y)) * 22ms);
}
.mup-resume[data-state="done"] .mup-resume__grid i { animation-name: mup-resume-settle; background: var(--mup-resume-accent); }
@keyframes mup-resume-wave { 40% { background: color-mix(in oklab, white 70%, var(--mup-resume-accent)); scale: 1.25; } }
@keyframes mup-resume-settle { from { scale: .6; opacity: .4; } }
.mup-resume[data-state="cancelled"] .mup-resume__grid i { transition-delay: calc((var(--mup-resume-cols) - var(--x) + var(--y)) * 12ms); }

.mup-resume__legend {
  grid-area: legend; display: flex; flex-wrap: wrap; gap: 4px 14px; margin-top: 8px;
  font-size: 11px; color: var(--mup-resume-dim); font-variant-numeric: tabular-nums;
  & li { display: flex; align-items: center; gap: 5px; }
  & i { width: 8px; height: 8px; border-radius: 2px; background: var(--mup-resume-cell); }
  & li[data-k="ok"] i { background: var(--mup-resume-done); }
  & li[data-k="fly"] i { background: var(--mup-resume-accent); box-shadow: 0 0 6px var(--mup-resume-accent); }
  & b { color: var(--mup-resume-ink); font-weight: 650; font-family: ui-monospace, Menlo, monospace; font-size: 11px; }
}

/* ---------- throughput sparkline ---------- */
.mup-resume__spark {
  grid-area: spark; display: grid; grid-template-columns: minmax(0, 1fr); margin-top: 12px; padding-top: 10px;
  border-top: 1px solid var(--mup-resume-line);
  & p { display: flex; justify-content: space-between; align-items: baseline; font-size: 11px; color: var(--mup-resume-dim); margin-bottom: 4px; }
  & b { font: 650 11.5px/1 ui-monospace, Menlo, monospace; color: var(--mup-resume-ink); font-variant-numeric: tabular-nums; }
  & canvas { display: block; width: 100%; height: 46px; }
}

/* ---------- status and controls ---------- */
.mup-resume__foot { grid-area: foot; display: grid; gap: 10px; margin-top: 10px; }
.mup-resume__status {
  min-height: 1.4em; font-size: 12px; color: var(--mup-resume-dim); text-wrap: pretty; font-variant-numeric: tabular-nums;
  & b { color: var(--mup-resume-ink); font-weight: 650; }
}
.mup-resume[data-state="offline"] .mup-resume__status { color: color-mix(in oklab, var(--mup-resume-danger) 75%, var(--mup-resume-ink)); }
.mup-resume[data-state="done"] .mup-resume__status { color: var(--mup-resume-ink); }
.mup-resume__ctrls { display: flex; flex-wrap: wrap; gap: 6px; }
.mup-resume__primary, .mup-resume__ghost, .mup-resume__danger {
  display: inline-flex; align-items: center; gap: 6px; height: 32px; padding: 0 12px; border-radius: 9px; white-space: nowrap;
  font-size: 12.5px; font-weight: 650;
  transition: background-color .15s, color .15s, scale .3s var(--mup-resume-spring), opacity .2s;
  & svg { width: 16px; height: 16px; }
  &:active:not(:disabled) { scale: .95; }
  &:disabled { opacity: .38; cursor: not-allowed; }
}
.mup-resume__primary {
  padding-left: 10px; color: oklch(0.22 0.03 70); background: var(--mup-resume-accent);
  box-shadow: inset 0 1px 0 color-mix(in oklab, white 40%, transparent);
  &:hover:not(:disabled) { background: color-mix(in oklab, white 14%, var(--mup-resume-accent)); }
  & svg { stroke-width: 2.2; }
  & path { opacity: 0; scale: .5; transform-origin: 12px 12px; transition: opacity .2s, scale .35s var(--mup-resume-spring); }
}
.mup-resume[data-state="run"] .mup-resume__gpause,
.mup-resume[data-state="offline"] .mup-resume__gpause,
.mup-resume[data-state="paused"] .mup-resume__gplay,
.mup-resume:is([data-state="done"], [data-state="cancelled"]) .mup-resume__gagain { opacity: 1; scale: 1; }
.mup-resume__gplay { fill: currentColor; }
.mup-resume__ghost {
  color: var(--mup-resume-dim); box-shadow: inset 0 0 0 1px var(--mup-resume-line);
  &:hover:not(:disabled) { color: var(--mup-resume-ink); background: color-mix(in oklab, var(--mup-resume-ink) 7%, transparent); }
}
.mup-resume[data-state="offline"] [data-act="drop"] { color: var(--mup-resume-ink); box-shadow: inset 0 0 0 1px var(--mup-resume-danger); }
.mup-resume__cancel { margin-left: auto; }
.mup-resume__danger {
  color: white; background: var(--mup-resume-danger);
  &:hover { background: color-mix(in oklab, black 12%, var(--mup-resume-danger)); }
}

/* ---------- confirm: a sheet that rises inside the card ---------- */
.mup-resume__confirm {
  position: absolute; left: 8px; right: 8px; bottom: 8px; z-index: 5; display: grid; gap: 4px; padding: 14px;
  border-radius: 13px; background: color-mix(in oklab, var(--mup-resume-ink) 9%, var(--mup-resume-bg));
  box-shadow: 0 0 0 1px var(--mup-resume-line), 0 -18px 40px -10px color-mix(in oklab, black 70%, transparent);
  translate: 0 calc(100% + 12px); visibility: hidden;
  transition: translate .45s var(--mup-resume-ease), visibility 0s .45s;
  & div { display: flex; justify-content: flex-end; gap: 6px; margin-top: 10px; }
}
.mup-resume__ctitle { font-size: 14px; font-weight: 700; letter-spacing: -.01em; text-wrap: balance; }
.mup-resume__csub { font-size: 12px; color: var(--mup-resume-dim); text-wrap: pretty; }
.mup-resume[data-confirm] .mup-resume__confirm { translate: 0 0; visibility: visible; transition: translate .5s var(--mup-resume-spring), visibility 0s; }
.mup-resume[data-confirm]::after {
  content: ""; position: absolute; inset: 0; z-index: 4; background: color-mix(in oklab, black 40%, transparent);
  animation: mup-resume-fade .3s both;
}
@keyframes mup-resume-fade { from { opacity: 0; } }
.mup-resume__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

@container (max-width: 330px) {
  .mup-resume__grid { --mup-resume-cols: 20; }
  .mup-resume__eyebrow { display: none; }
  .mup-resume__cancel { margin-left: 0; }
}
@container (min-width: 520px) {
  .mup-resume__grid { --mup-resume-cols: 30; }
}

@media (prefers-reduced-motion: reduce) {
  .mup-resume__grid i, .mup-resume__confirm, .mup-resume__primary path, .mup-resume__primary, .mup-resume__ghost { transition-duration: .01s; transition-delay: 0s; }
  .mup-resume__grid i[data-s="fly"] { scale: 1; box-shadow: 0 0 0 1px var(--mup-resume-accent); }
  .mup-resume__grid i[data-s="err"] { scale: 1; }
  .mup-resume[data-state="verify"] .mup-resume__grid i, .mup-resume[data-state="done"] .mup-resume__grid i { animation: none; }
  .mup-resume[data-confirm]::after { animation: none; }
}

