const $ = (s, el = root) => el.querySelector(s);
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const later = (ms, fn) => setTimeout(() => { if (root.isConnected) fn(); }, ms);

const N = 240, CH = 8, TOTAL = N * CH, STREAMS = 3, START = 96, HIST = 120;
const grid = $('.mup-resume__grid'), cv = $('.mup-resume__spark canvas'), g = cv.getContext('2d');
const pctEl = $('[data-pct]'), metaEl = $('[data-meta]'), statusEl = $('[data-status]'), rateEl = $('[data-rate]'), live = $('.mup-resume__sr');
const nOk = $('[data-n="ok"]'), nFly = $('[data-n="fly"]'), nWait = $('[data-n="wait"]');
const pauseBtn = $('[data-act="pause"]'), pauseLbl = $('[data-pause]'), dropBtn = $('[data-act="drop"]'), dropLbl = $('[data-drop]');
const cancelBtn = $('[data-act="cancel"]'), sheet = $('.mup-resume__confirm'), ctitle = $('[data-ctitle]');
const keepBtn = $('[data-act="keep"]'), discardBtn = $('[data-act="discard"]');
ctitle.id = 'mup-resume-c-' + Math.random().toString(36).slice(2, 8);
sheet.setAttribute('aria-labelledby', ctitle.id);

const say = (m) => { live.textContent = ''; later(40, () => { live.textContent = m; }); };
const mb = (v) => v.toLocaleString('en-US', { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const secs = (s) => s >= 60 ? Math.floor(s / 60) + 'm ' + String(Math.round(s % 60)).padStart(2, '0') + 's' : Math.max(1, Math.round(s)) + ' s';

/* ---------- model ---------- */
const cells = [];
for (let i = 0; i < N; i++) { const el = document.createElement('i'); grid.append(el); cells.push({ el, s: i < START ? 'ok' : '', p: 0 }); }
let fly = [], state = 'run', raf = 0, last = 0, onscreen = true, ema = 0, hist = new Array(HIST).fill(0), histAcc = 0;
let attempt = 0, retryAt = 0, shownSec = -1, sessBytes = 0, sessT = 0, resumedAt = START, statusBase = '', lastStats = 0;
let accent = '#e0b050', dpr = 1, W = 0, H = 0;

function paint(c) {
  if (c.el.dataset.s !== c.s) c.el.dataset.s = c.s;
  if (c.s === 'fly') c.el.style.setProperty('--mup-resume-p', c.p.toFixed(3));
}
cells.forEach(paint);
const okCount = () => cells.reduce((a, c) => a + (c.s === 'ok'), 0);
const sent = () => cells.reduce((a, c) => a + (c.s === 'ok' ? CH : c.s === 'fly' ? c.p * CH : 0), 0);
const nextPending = () => cells.findIndex((c) => c.s === '');

function stats(force) {
  const now = performance.now();
  if (!force && now - lastStats < 120) return;
  lastStats = now;
  const ok = okCount(), s = sent(), pct = Math.floor((s / TOTAL) * 100);
  pctEl.textContent = pct;
  grid.setAttribute('aria-valuenow', pct);
  grid.setAttribute('aria-valuetext', pct + '%, ' + ok + ' of ' + N + ' chunks verified');
  nOk.textContent = ok; nFly.textContent = fly.length; nWait.textContent = N - ok - fly.length;
  const tail = state === 'run' ? (ema > 0.5 ? mb(ema) + ' MB/s · ' + secs((TOTAL - s) / ema) + ' left' : 'starting…')
    : state === 'paused' ? 'paused' : state === 'offline' ? 'waiting for network' : state === 'verify' ? 'verifying' : state === 'done' ? 'delivered' : 'discarded';
  metaEl.innerHTML = '<b>' + mb(s) + '</b> of 1,920 MB · ' + tail;
  rateEl.textContent = mb(ema) + ' MB/s';
}
function setStatus(html) { statusBase = html; statusEl.innerHTML = html; }
function setState(s) {
  state = s;
  root.dataset.state = s;
  pauseLbl.textContent = s === 'paused' ? 'Resume' : s === 'done' || s === 'cancelled' ? 'Upload again' : 'Pause';
  pauseBtn.disabled = s === 'verify';
  dropLbl.textContent = s === 'offline' ? 'Retry now' : 'Drop connection';
  dropBtn.disabled = s !== 'run' && s !== 'offline';
  cancelBtn.disabled = s === 'done' || s === 'cancelled' || s === 'verify';
  stats(true);
  kick();
}

/* ---------- the simulation: three streams, chunk-level resume, exponential backoff ---------- */
function tick(t) {
  if (!root.isConnected) { io.disconnect(); ro.disconnect(); return; }
  raf = 0;
  const dt = Math.min(0.1, (t - last) / 1000);
  last = t;
  let moved = 0;
  if (state === 'run') {
    while (fly.length < STREAMS) {
      const k = nextPending();
      if (k < 0) break;
      cells[k].s = 'fly'; cells[k].p = 0; fly.push(k); paint(cells[k]);
    }
    for (const k of fly.slice()) {
      const c = cells[k];
      const v = 12.6 + 3.2 * Math.sin(t / 900 + k * 0.7) + 1.6 * Math.sin(t / 260 + k * 1.9);
      const add = Math.min(v * dt, (1 - c.p) * CH);
      c.p += add / CH; moved += add;
      if (c.p >= 0.999) { c.s = 'ok'; c.p = 0; fly.splice(fly.indexOf(k), 1); }
      paint(c);
    }
    sessBytes += moved; sessT += dt;
    if (okCount() === N) {
      setState('verify');
      setStatus('Verifying SHA-256 across <b>240</b> chunks…');
      say('All chunks uploaded. Verifying checksum.');
      later(RM.matches ? 300 : 1300, () => {
        setState('done');
        setStatus('Delivered · checksum <b>9f2c 41d0 … e41a</b> matches · ' + mb(sessBytes) + ' MB this session in ' + secs(sessT));
        say('Delivered. Checksum matches. ' + mb(sessBytes) + ' megabytes uploaded this session in ' + secs(sessT) + '.');
      });
    }
  } else if (state === 'offline') {
    const left = Math.max(0, Math.ceil((retryAt - t) / 1000));
    if (t >= retryAt) {
      attempt++;
      if (attempt === 1) { retryAt = t + 4000; say('Retry 1 failed. Next try in 4 seconds.'); }
      else reconnect('automatically');
    } else if (left !== shownSec) {
      shownSec = left;
      statusEl.innerHTML = (attempt ? 'Retry ' + attempt + ' failed · ' : 'Connection lost · ') + 'next try in <b>' + left + ' s</b> · ' + okCount() + ' verified chunks are safe';
    }
  }
  const inst = dt > 0 ? moved / dt : 0;
  ema += (inst - ema) * Math.min(1, dt * 2.5);
  if (ema < 0.05 && state !== 'run') ema = 0;
  histAcc += dt;
  if (histAcc >= 0.25) { histAcc = 0; hist.push(ema); hist.shift(); draw(); }
  stats(false);
  if (onscreen && (state === 'run' || state === 'offline' || ema > 0)) raf = requestAnimationFrame(tick);
}
function kick() {
  if (raf || !onscreen) return;
  last = performance.now();
  raf = requestAnimationFrame(tick);
}

function returnFlying(flash) {
  const back = fly.slice();
  fly = [];
  back.forEach((k) => {
    const c = cells[k];
    c.p = 0; c.s = flash ? 'err' : ''; paint(c);
    if (flash) later(RM.matches ? 0 : 420, () => { if (c.s === 'err') { c.s = ''; paint(c); } });
  });
  return back.length;
}
function reconnect(how) {
  const k = nextPending();
  attempt = 0; shownSec = -1; resumedAt = k + 1;
  setState('run');
  setStatus('Reconnected ' + how + ' · resuming at chunk <b>' + (k + 1) + '</b>');
  say('Reconnected. Resuming at chunk ' + (k + 1) + '.');
}

pauseBtn.addEventListener('click', () => {
  if (state === 'run' || state === 'offline') {
    const lost = returnFlying(false), ok = okCount();
    setState('paused');
    setStatus('Paused · <b>' + ok + '</b> verified chunks kept on the server' + (lost ? ', ' + lost + ' partial ' + (lost === 1 ? 'chunk' : 'chunks') + ' dropped' : ''));
    say('Paused. ' + ok + ' of ' + N + ' chunks are verified and kept. Resume continues at chunk ' + (nextPending() + 1) + '.');
  } else if (state === 'paused') {
    const k = nextPending();
    setState('run');
    setStatus('Resumed at chunk <b>' + (k + 1) + '</b> · ' + (okCount() * CH).toLocaleString('en-US') + ' MB already verified');
    say('Resumed at chunk ' + (k + 1) + '.');
  } else if (state === 'done' || state === 'cancelled') {
    cells.forEach((c) => { c.s = ''; c.p = 0; paint(c); });
    sessBytes = 0; sessT = 0; ema = 0;
    setState('run');
    setStatus('Uploading from chunk <b>1</b> · 3 parallel streams');
    say('Upload started.');
  }
});
dropBtn.addEventListener('click', () => {
  if (state === 'offline') { reconnect('manually'); return; }
  if (state !== 'run') return;
  const lost = returnFlying(true);
  attempt = 0; shownSec = -1; retryAt = performance.now() + 2000;
  setState('offline');
  setStatus('Connection lost · ' + lost + ' in-flight chunks returned to the queue');
  say('Connection lost. ' + lost + ' chunks in flight go back to the queue. Retrying in 2 seconds, then 4.');
});

/* ---------- cancel asks first, inside the card ---------- */
function openSheet() {
  ctitle.textContent = 'Discard ' + (okCount() * CH).toLocaleString('en-US') + ' MB already uploaded?';
  root.setAttribute('data-confirm', '');
  sheet.setAttribute('aria-hidden', 'false');
  keepBtn.tabIndex = 0; discardBtn.tabIndex = 0;
  later(RM.matches ? 0 : 120, () => keepBtn.focus());
}
function closeSheet(refocus) {
  root.removeAttribute('data-confirm');
  sheet.setAttribute('aria-hidden', 'true');
  keepBtn.tabIndex = -1; discardBtn.tabIndex = -1;
  if (refocus) refocus.focus();
}
cancelBtn.addEventListener('click', openSheet);
keepBtn.addEventListener('click', () => closeSheet(cancelBtn));
discardBtn.addEventListener('click', () => {
  closeSheet(null);
  const freed = okCount() * CH;
  fly = [];
  cells.forEach((c) => { c.s = ''; c.p = 0; paint(c); });
  setState('cancelled');
  setStatus('Upload discarded · ' + freed.toLocaleString('en-US') + ' MB removed from the server');
  pauseBtn.focus();
  say('Upload discarded.');
});
sheet.addEventListener('keydown', (e) => {
  if (e.key === 'Escape') { e.preventDefault(); closeSheet(cancelBtn); }
  else if (e.key === 'Tab') { e.preventDefault(); (document.activeElement === keepBtn ? discardBtn : keepBtn).focus(); }
  else if (e.key === 'ArrowLeft' || e.key === 'ArrowRight') { e.preventDefault(); (document.activeElement === keepBtn ? discardBtn : keepBtn).focus(); }
});

/* ---------- sparkline: DPR-aware canvas, sized by ResizeObserver ---------- */
function draw() {
  if (!W) return;
  const w = cv.width, h = cv.height, top = 3 * dpr, bot = h - 2 * dpr, max = 48;
  g.clearRect(0, 0, w, h);
  g.strokeStyle = accent; g.globalAlpha = 0.14; g.lineWidth = 1;
  g.setLineDash([2 * dpr, 3 * dpr]);
  for (const v of [16, 32]) { const y = Math.round(bot - (v / max) * (bot - top)) + 0.5; g.beginPath(); g.moveTo(0, y); g.lineTo(w, y); g.stroke(); }
  g.setLineDash([]);
  g.globalAlpha = 1;
  const x = (i) => (i / (HIST - 1)) * (w - 4 * dpr), y = (v) => bot - (Math.min(v, max) / max) * (bot - top);
  g.beginPath();
  hist.forEach((v, i) => (i ? g.lineTo(x(i), y(v)) : g.moveTo(x(i), y(v))));
  g.lineTo(x(HIST - 1), bot); g.lineTo(0, bot); g.closePath();
  const grad = g.createLinearGradient(0, top, 0, bot);
  grad.addColorStop(0, accent); grad.addColorStop(1, 'rgba(0,0,0,0)');
  g.fillStyle = grad; g.globalAlpha = 0.32; g.fill(); g.globalAlpha = 1;
  g.beginPath();
  hist.forEach((v, i) => (i ? g.lineTo(x(i), y(v)) : g.moveTo(x(i), y(v))));
  g.strokeStyle = accent; g.lineWidth = 1.6 * dpr; g.lineJoin = 'round'; g.stroke();
  const ex = x(HIST - 1), ey = y(hist[HIST - 1]);
  g.fillStyle = accent; g.beginPath(); g.arc(ex, ey, 2.6 * dpr, 0, Math.PI * 2); g.fill();
}
function layout() {
  const r = cv.getBoundingClientRect();
  if (!r.width) return;
  dpr = Math.min(2, window.devicePixelRatio || 1);
  W = r.width; H = r.height;
  cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);
  accent = getComputedStyle(root).getPropertyValue('--mup-resume-accent').trim() || accent;
  const cols = parseInt(getComputedStyle(grid).getPropertyValue('--mup-resume-cols'), 10) || 24;
  cells.forEach((c, i) => { c.el.style.setProperty('--x', i % cols); c.el.style.setProperty('--y', Math.floor(i / cols)); });
  draw();
}
const ro = new ResizeObserver(() => { if (!root.isConnected) { ro.disconnect(); return; } layout(); });
ro.observe(root);

/* the loop runs only while the card is on screen */
const io = new IntersectionObserver((es) => {
  if (!root.isConnected) { io.disconnect(); return; }
  onscreen = es[es.length - 1].isIntersecting;
  if (onscreen) kick();
});
io.observe(root);

for (let i = 0; i < HIST; i++) hist[i] = i < 70 ? 34 + 6 * Math.sin(i / 5) + 3 * Math.sin(i * 1.3) : 0;
ema = 0;
setStatus('Resumed at chunk <b>97</b> · 768 MB was already on the server');
setState('run');
layout();

