@property --mup-guard-fl { syntax: "<length>"; inherits: false; initial-value: 0px; }
@property --mup-guard-fr { syntax: "<length>"; inherits: false; initial-value: 0px; }

/* Re-theme with --mup-guard-bg, -ink, -pass, -block and -mark. */
.mup-guard {
  --mup-guard-bg: oklch(0.968 0.009 168);
  --mup-guard-ink: oklch(0.25 0.025 215);
  --mup-guard-pass: oklch(0.52 0.12 160);
  --mup-guard-block: oklch(0.55 0.19 27);
  --mup-guard-mark: oklch(0.87 0.13 86);

  --mup-guard-dim: color-mix(in oklab, var(--mup-guard-ink) 58%, var(--mup-guard-bg));
  --mup-guard-faint: color-mix(in oklab, var(--mup-guard-ink) 30%, var(--mup-guard-bg));
  --mup-guard-line: color-mix(in oklab, var(--mup-guard-ink) 12%, var(--mup-guard-bg));
  --mup-guard-paper: color-mix(in oklab, white 78%, var(--mup-guard-bg));
  --mup-guard-tone: var(--mup-guard-dim);
  --mup-guard-ease: cubic-bezier(.22, 1, .36, 1);
  --mup-guard-spring: linear(0, 0.034 2.3%, 0.13 4.7%, 0.484 11.6%, 0.656 15.5%, 0.786 19.5%, 0.883 23.6%, 0.951 27.9%, 1.006 33.3%, 1.03 38.5%, 1.037 44.2%, 1.025 54.1%, 1.008 66.8%, 1);

  container-type: inline-size;
  position: relative;
  display: grid;
  grid-template-areas: "head" "rules" "files" "panel" "foot";
  grid-template-columns: minmax(0, 1fr);
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  padding: 14px;
  border-radius: 16px;
  background: var(--mup-guard-bg);
  color: var(--mup-guard-ink);
  box-shadow: 0 0 0 1px var(--mup-guard-line), 0 18px 40px -30px color-mix(in oklab, var(--mup-guard-ink) 70%, transparent);
  font: 400 13px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-align: left;
  accent-color: var(--mup-guard-ink);
}
.mup-guard[data-verdict="pass"] { --mup-guard-tone: var(--mup-guard-pass); }
.mup-guard[data-verdict="block"] { --mup-guard-tone: var(--mup-guard-block); }
@supports not (transition-timing-function: linear(0, 1)) {
  .mup-guard { --mup-guard-spring: cubic-bezier(.3, 1.35, .5, 1); }
}
:where(.mup-guard) *, :where(.mup-guard) *::before, :where(.mup-guard) *::after { box-sizing: border-box; }
:where(.mup-guard) :is(p, h3, ul, li) { margin: 0; padding: 0; list-style: none; }
:where(.mup-guard) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
:where(.mup-guard) :focus-visible { outline: 2px solid var(--mup-guard-ink); outline-offset: 2px; }
.mup-guard .mup-guard__i { fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }

.mup-guard__head {
  grid-area: head; display: flex; align-items: end; justify-content: space-between; gap: 10px;
  & div { min-width: 0; }
  & h3 { font-size: clamp(15px, 5cqi, 18px); font-weight: 750; letter-spacing: -.02em; line-height: 1.15; text-wrap: balance; }
}
.mup-guard__eyebrow {
  font: 600 10.5px/1.3 ui-monospace, Menlo, monospace; letter-spacing: .06em; text-transform: uppercase; color: var(--mup-guard-dim);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; margin-bottom: 3px;
}
.mup-guard__rules { grid-area: rules; margin-top: 5px; font-size: 11.5px; color: var(--mup-guard-dim); text-wrap: pretty; }
.mup-guard__ghost {
  display: inline-flex; align-items: center; gap: 6px; flex: none; height: 30px; padding: 0 11px 0 9px; border-radius: 8px;
  font-size: 12px; font-weight: 600; background: var(--mup-guard-paper); box-shadow: inset 0 0 0 1px var(--mup-guard-line);
  transition: background-color .15s, scale .3s var(--mup-guard-spring);
  & svg { width: 15px; height: 15px; }
  &:hover { background: color-mix(in oklab, var(--mup-guard-ink) 5%, var(--mup-guard-paper)); }
  &:active { scale: .95; }
}

/* ---------- sample files: a radiogroup that scrolls sideways ---------- */
.mup-guard__files {
  grid-area: files; display: flex; gap: 6px; margin: 10px -14px 0; padding: 2px 14px 4px; overflow-x: auto;
  scroll-snap-type: x proximity; scroll-padding-inline: 14px; scrollbar-width: none;
  &::-webkit-scrollbar { display: none; }
}
@supports (animation-timeline: scroll()) {
  .mup-guard__files {
    mask-image: linear-gradient(90deg, transparent, #000 var(--mup-guard-fl), #000 calc(100% - var(--mup-guard-fr)), transparent);
    animation: mup-guard-edges linear both; animation-timeline: scroll(self inline);
  }
  @keyframes mup-guard-edges {
    0% { --mup-guard-fl: 0px; --mup-guard-fr: 26px; }
    10% { --mup-guard-fl: 26px; }
    90% { --mup-guard-fr: 26px; }
    100% { --mup-guard-fl: 26px; --mup-guard-fr: 0px; }
  }
}
.mup-guard__file {
  flex: none; display: inline-flex; align-items: center; gap: 6px; height: 30px; padding: 0 10px 0 5px; border-radius: 8px;
  scroll-snap-align: start; white-space: nowrap; font: 550 11.5px/1 ui-monospace, Menlo, monospace; letter-spacing: -.02em;
  background: var(--mup-guard-paper); box-shadow: inset 0 0 0 1px var(--mup-guard-line);
  transition: background-color .2s, color .2s, box-shadow .2s, scale .3s var(--mup-guard-spring);
  & i {
    padding: 3px 4px; border-radius: 4px; font: 700 8.5px/1 ui-monospace, Menlo, monospace; font-style: normal; letter-spacing: .04em;
    background: color-mix(in oklab, var(--mup-guard-ink) 9%, transparent);
  }
  &:hover { box-shadow: inset 0 0 0 1px var(--mup-guard-faint); }
  &:active { scale: .96; }
  &[aria-checked="true"] { background: var(--mup-guard-ink); color: var(--mup-guard-bg); box-shadow: none; }
  &[aria-checked="true"] i { background: color-mix(in oklab, var(--mup-guard-bg) 20%, transparent); }
}

/* ---------- inspection panel ---------- */
.mup-guard__panel {
  grid-area: panel; position: relative; overflow: hidden; margin-top: 8px; padding: 11px 12px 12px; border-radius: 12px;
  background: var(--mup-guard-paper); box-shadow: inset 0 0 0 1px var(--mup-guard-line);
}
.mup-guard__ph { display: grid; gap: 2px; padding-right: 92px; margin-bottom: 10px; min-height: 34px; }
.mup-guard__fname { font: 650 12.5px/1.3 ui-monospace, Menlo, monospace; letter-spacing: -.02em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mup-guard__fmeta {
  display: flex; align-items: center; gap: 6px; min-width: 0; font-size: 11px; color: var(--mup-guard-dim); font-variant-numeric: tabular-nums;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  & b { font-weight: 600; color: var(--mup-guard-ink); opacity: 0; transition: opacity .3s; }
  & b::before { content: "·"; margin-right: 6px; color: var(--mup-guard-faint); }
}
.mup-guard[data-match] .mup-guard__fmeta b { opacity: 1; }

/* hex dump: 16 bytes, offsets, ascii gutter */
.mup-guard__hex {
  position: relative; display: grid; grid-template-columns: auto repeat(8, minmax(0, 1fr)) auto; align-items: center; gap: 3px 2px;
  padding: 8px 8px; border-radius: 8px; background: color-mix(in oklab, var(--mup-guard-ink) 4%, var(--mup-guard-paper));
  font: 500 12px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; overflow: hidden;
  & .mup-guard__off { padding-right: 8px; font-size: 10px; color: var(--mup-guard-faint); }
  & .mup-guard__asc { padding-left: 10px; font-size: 11px; color: var(--mup-guard-dim); letter-spacing: .08em; white-space: pre; }
  & b {
    position: relative; display: grid; place-items: center; height: 21px; border-radius: 4px; font-weight: 550;
    opacity: 0; translate: 0 4px; transition: opacity .25s, translate .4s var(--mup-guard-ease), background-color .3s, color .3s, scale .45s var(--mup-guard-spring);
    transition-delay: calc(var(--i) * 22ms);
  }
  /* the read head sweeps once across the bytes */
  &::after {
    content: ""; position: absolute; top: 0; bottom: 0; left: 0; width: 34%; pointer-events: none;
    background: linear-gradient(90deg, transparent, color-mix(in oklab, var(--mup-guard-mark) 55%, transparent), transparent);
    translate: -110% 0; opacity: 0;
  }
}
.mup-guard[data-read] .mup-guard__hex b { opacity: 1; translate: 0 0; }
.mup-guard[data-read]:not([data-match]) .mup-guard__hex::after { animation: mup-guard-sweep .6s var(--mup-guard-ease); }
@keyframes mup-guard-sweep { 0% { translate: -110% 0; opacity: 1; } 100% { translate: 320% 0; opacity: 1; } }
.mup-guard[data-match] .mup-guard__hex b[data-m] {
  background: var(--mup-guard-mark); color: oklch(0.25 0.05 70); font-weight: 750; scale: 1.06;
  transition-delay: calc(var(--m) * 70ms);
}
.mup-guard[data-match] .mup-guard__hex b[data-m][data-bad] { background: color-mix(in oklab, var(--mup-guard-block) 22%, var(--mup-guard-paper)); color: var(--mup-guard-block); }
.mup-guard__sig {
  margin-top: 7px; font-size: 11.5px; color: var(--mup-guard-dim); min-height: 1.4em;
  opacity: 0; transition: opacity .3s .2s;
  & b { color: var(--mup-guard-ink); font-weight: 650; }
  & code { font: 600 11px/1 ui-monospace, Menlo, monospace; padding: 2px 4px; border-radius: 4px; background: var(--mup-guard-mark); color: oklch(0.25 0.05 70); }
}
.mup-guard[data-match] .mup-guard__sig { opacity: 1; }
.mup-guard__sig[data-bad] code { background: color-mix(in oklab, var(--mup-guard-block) 18%, var(--mup-guard-paper)); color: var(--mup-guard-block); }

/* checklist */
.mup-guard__checks { display: grid; gap: 5px; margin-top: 10px; padding-top: 10px; border-top: 1px dashed var(--mup-guard-line); }
.mup-guard__check {
  display: grid; grid-template-columns: auto minmax(0, 1fr); align-items: start; column-gap: 8px;
  opacity: 0; translate: 0 5px; transition: opacity .3s, translate .45s var(--mup-guard-ease); transition-delay: calc(var(--i) * 120ms);
  & > span:first-child {
    display: grid; place-items: center; width: 17px; height: 17px; margin-top: 1px; border-radius: 50%; color: white;
    background: var(--mup-guard-pass); scale: .4; transition: scale .5s var(--mup-guard-spring); transition-delay: calc(var(--i) * 120ms + 90ms);
  }
  & svg { width: 11px; height: 11px; stroke-width: 3; }
  & p { font-size: 12px; font-weight: 600; line-height: 1.35; text-wrap: pretty; }
  & small { display: block; font-size: 11px; font-weight: 400; color: var(--mup-guard-dim); }
}
.mup-guard__check[data-ok="0"] > span:first-child { background: var(--mup-guard-block); }
.mup-guard__check[data-ok="0"] p { color: var(--mup-guard-block); }
.mup-guard[data-checks] .mup-guard__check { opacity: 1; translate: 0 0; }
.mup-guard[data-checks] .mup-guard__check > span:first-child { scale: 1; }

/* the stamp lands last */
.mup-guard__stamp {
  position: absolute; top: 12px; right: 12px; padding: 5px 9px 4px; border-radius: 5px;
  font: 800 12.5px/1 ui-monospace, Menlo, monospace; letter-spacing: .16em; text-transform: uppercase; color: var(--mup-guard-tone);
  border: 2px solid currentColor; box-shadow: inset 0 0 0 2px var(--mup-guard-paper), inset 0 0 0 3.5px currentColor;
  mask-image: repeating-linear-gradient(112deg, #000 0 3px, rgb(0 0 0 / .72) 3px 4px, #000 4px 7px);
  rotate: -16deg; scale: 1.9; opacity: 0; pointer-events: none;
}
.mup-guard[data-done] .mup-guard__stamp { rotate: -7deg; scale: 1; opacity: .92; transition: rotate .5s var(--mup-guard-spring), scale .5s var(--mup-guard-spring), opacity .15s; }

/* ---------- verdict ---------- */
.mup-guard__foot {
  grid-area: foot; position: relative; display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 9px;
  margin-top: 10px; padding: 9px 9px 9px 10px; border-radius: 12px; overflow: hidden;
  background: color-mix(in oklab, var(--mup-guard-tone) 9%, var(--mup-guard-paper));
  box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--mup-guard-tone) 25%, transparent);
  transition: background-color .4s, box-shadow .4s;
}
.mup-guard__vico {
  display: grid; place-items: center; width: 26px; height: 26px; border-radius: 50%; color: white; background: var(--mup-guard-tone);
  transition: background-color .4s;
  & svg { width: 15px; height: 15px; stroke-width: 2.6; }
  & path { opacity: 0; transition: opacity .2s; }
}
.mup-guard[data-done][data-verdict="pass"] .mup-guard__vok, .mup-guard[data-done][data-verdict="block"] .mup-guard__vno { opacity: 1; }
.mup-guard:not([data-done]) .mup-guard__vico { background: transparent; box-shadow: inset 0 0 0 2px var(--mup-guard-line); }
.mup-guard:not([data-done]) .mup-guard__vico::after {
  content: ""; width: 26px; height: 26px; grid-area: 1 / 1; border-radius: 50%; border: 2px solid transparent; border-top-color: var(--mup-guard-ink);
  animation: mup-guard-spin .8s linear infinite;
}
@keyframes mup-guard-spin { to { rotate: 1turn; } }
.mup-guard__verdict {
  font-size: 12.5px; font-weight: 650; line-height: 1.3; text-wrap: pretty;
  & small { display: block; font-size: 11px; font-weight: 450; color: var(--mup-guard-dim); }
}
.mup-guard[data-verdict="block"][data-done] .mup-guard__verdict { color: var(--mup-guard-block); }
.mup-guard__primary {
  height: 32px; padding: 0 13px; border-radius: 9px; white-space: nowrap; font-size: 12.5px; font-weight: 650;
  color: var(--mup-guard-bg); background: var(--mup-guard-ink); font-variant-numeric: tabular-nums;
  transition: background-color .15s, scale .3s var(--mup-guard-spring), opacity .2s;
  &:hover:not(:disabled) { background: color-mix(in oklab, white 14%, var(--mup-guard-ink)); }
  &:active:not(:disabled) { scale: .95; }
  &:disabled { opacity: .35; cursor: default; }
}
.mup-guard[data-verdict="pass"] .mup-guard__primary { background: var(--mup-guard-pass); color: white; }
.mup-guard__prog {
  position: absolute; left: 0; bottom: 0; height: 3px; width: 100%; background: var(--mup-guard-pass);
  transform-origin: left; transform: scaleX(var(--mup-guard-p, 0)); opacity: 0; transition: opacity .3s;
}
.mup-guard[data-up] .mup-guard__prog { opacity: 1; }
.mup-guard__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

@container (max-width: 330px) {
  .mup-guard__hex .mup-guard__asc { display: none; }
  .mup-guard__hex { grid-template-columns: auto repeat(8, minmax(0, 1fr)); }
  .mup-guard__ghost span { display: none; }
  .mup-guard__ph { padding-right: 80px; }
  .mup-guard__stamp { font-size: 11px; letter-spacing: .12em; top: 14px; right: 10px; }
}

@media (prefers-reduced-motion: reduce) {
  .mup-guard__hex b, .mup-guard__check, .mup-guard__check > span:first-child, .mup-guard__sig { transition-duration: .01s; transition-delay: 0s; }
  .mup-guard[data-read]:not([data-match]) .mup-guard__hex::after { animation: none; }
  .mup-guard[data-done] .mup-guard__stamp { transition: opacity .2s; rotate: -7deg; scale: 1; }
  .mup-guard__stamp { rotate: -7deg; scale: 1; }
  .mup-guard:not([data-done]) .mup-guard__vico::after { animation-duration: 2.4s; }
}

