const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

const files = $('.mup-guard__files'), hex = $('.mup-guard__hex'), checksEl = $('.mup-guard__checks'), stamp = $('[data-stamp]');
const fname = $('[data-fname]'), fsize = $('[data-fsize]'), kindEl = $('[data-kind]'), sigEl = $('[data-sig]');
const verdictEl = $('[data-verdict-text]'), goBtn = $('[data-act="go"]'), goLbl = $('[data-go]'), prog = $('.mup-guard__prog');
const input = $('.mup-guard__input'), live = $('.mup-guard__sr');

let timers = [], cur = null, run = 0, upRaf = 0;
const later = (ms, fn) => { const id = setTimeout(() => { if (root.isConnected) fn(); }, ms); timers.push(id); return id; };
const say = (m) => { live.textContent = ''; setTimeout(() => { if (root.isConnected) live.textContent = m; }, 40); };
const fmt = (b) => b < 1e6 ? Math.max(1, Math.round(b / 1e3)) + ' KB' : (b / 1e6).toFixed(1) + ' MB';
const extOf = (n) => (n.includes('.') ? n.split('.').pop() : '').toLowerCase();
const hx = (s) => s.split(' ').map((x) => parseInt(x, 16));

/* ---------- five files a carrier might really send, with their real first 16 bytes ---------- */
const SAMPLES = [
  { name: 'pod-HF-20931.pdf', size: 412e3, bytes: hx('25 50 44 46 2D 31 2E 37 0A 25 E2 E3 CF D3 0A 31') },
  { name: 'dock-photo-0412.jpg', size: 2.8e6, bytes: hx('FF D8 FF E1 1C 46 45 78 69 66 00 00 4D 4D 00 2A') },
  { name: 'signed-pod.pdf.exe', size: 1.1e6, bytes: hx('4D 5A 90 00 03 00 00 00 04 00 00 00 FF FF 00 00') },
  { name: 'invoice-scan.pdf', size: 96e3, bytes: hx('50 4B 03 04 14 00 06 00 08 00 00 00 21 00 7A 9C') },
  { name: 'trailer-seal.heic', size: 31.4e6, bytes: hx('00 00 00 18 66 74 79 70 68 65 69 63 00 00 00 00') }
];
const SIGS = [
  { id: 'pdf', label: 'PDF document', at: 0, sig: [0x25, 0x50, 0x44, 0x46], show: '%PDF', a: 'a' },
  { id: 'png', label: 'PNG image', at: 0, sig: [0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A], show: '.PNG', a: 'a' },
  { id: 'jpg', label: 'JPEG image', at: 0, sig: [0xFF, 0xD8, 0xFF], show: 'FF D8 FF', a: 'a' },
  { id: 'gif', label: 'GIF image', at: 0, sig: [0x47, 0x49, 0x46, 0x38], show: 'GIF8', a: 'a' },
  { id: 'zip', label: 'ZIP archive', at: 0, sig: [0x50, 0x4B, 0x03, 0x04], show: 'PK', a: 'a' },
  { id: 'exe', label: 'Windows program', at: 0, sig: [0x4D, 0x5A], show: 'MZ', a: 'a' },
  { id: 'elf', label: 'Linux program', at: 0, sig: [0x7F, 0x45, 0x4C, 0x46], show: '.ELF', a: 'a' },
  { id: 'heic', label: 'HEIC photo', at: 4, sig: [0x66, 0x74, 0x79, 0x70, 0x68, 0x65, 0x69, 0x63], show: 'ftypheic', a: 'a' },
  { id: 'mp4', label: 'MP4 or MOV video', at: 4, sig: [0x66, 0x74, 0x79, 0x70], show: 'ftyp', a: 'an' },
  { id: 'gz', label: 'GZIP archive', at: 0, sig: [0x1F, 0x8B], show: '1F 8B', a: 'a' }
];
const ALLOW = { pdf: ['pdf'], png: ['png'], jpg: ['jpg', 'jpeg'] };
const MAX = 20e6;
const detect = (b) => SIGS.find((s) => s.sig.every((v, k) => b[s.at + k] === v)) || null;

/* ---------- the four checks, contents first ---------- */
function inspectFile(f) {
  const ext = extOf(f.name), sig = detect(f.bytes), out = [];
  const allowedExt = ['pdf', 'png', 'jpg', 'jpeg'].includes(ext);
  if (!sig) out.push({ ok: 0, t: 'Contents not recognised', d: 'No known signature in the first ' + f.bytes.length + ' bytes', s: 'unrecognised contents' });
  else {
    const where = 'Bytes ' + sig.at + '–' + (sig.at + sig.sig.length - 1) + ' read “' + sig.show + '”';
    if (!ALLOW[sig.id]) out.push({ ok: 0, t: 'Contents are ' + sig.a + ' ' + sig.label, d: where, s: sig.id === 'exe' || sig.id === 'elf' ? 'it’s ' + sig.a + ' ' + sig.label : 'it’s really ' + sig.a + ' ' + sig.label });
    else if (!ALLOW[sig.id].includes(ext)) out.push({ ok: 0, t: sig.label + ' named .' + (ext || '?'), d: where + ', the name says otherwise', s: 'contents don’t match the name' });
    else out.push({ ok: 1, t: 'Contents match: ' + sig.label, d: where });
  }
  out.push(allowedExt ? { ok: 1, t: 'Extension .' + ext + ' is accepted', d: 'Allowed: .pdf, .png, .jpg' }
    : { ok: 0, t: ext ? 'Extension .' + ext + ' isn’t accepted' : 'No file extension', d: 'Allowed: .pdf, .png, .jpg', s: ext ? '.' + ext + ' isn’t accepted' : 'no extension' });
  out.push(f.size <= MAX ? { ok: 1, t: fmt(f.size) + ' is under the limit', d: '20 MB per file' }
    : { ok: 0, t: fmt(f.size) + ' is over the limit', d: '20 MB per file', s: 'over 20 MB' });
  const dbl = /\.(pdf|png|jpe?g|docx?|xlsx?|txt)\.(exe|scr|js|bat|cmd|com|msi|vbs|ps1)$/i.test(f.name);
  const hidden = /[\u0000-\u001f‪-‮⁦-⁩]/.test(f.name);
  out.push(dbl ? { ok: 0, t: 'Double extension hides the real type', d: '“' + f.name.split('.').slice(-2).join('.') + '” ends in an executable', s: 'a program disguised as a ' + f.name.split('.').slice(-2)[0].toUpperCase() }
    : hidden ? { ok: 0, t: 'Name contains hidden characters', d: 'Direction or control characters', s: 'hidden characters in the name' }
    : f.name.length > 120 ? { ok: 0, t: 'Name is longer than 120 characters', d: f.name.length + ' characters', s: 'name too long' }
    : { ok: 1, t: 'File name is clean', d: 'No double extension or hidden characters' });
  return { sig, out };
}

/* ---------- radiogroup of files ---------- */
let list = SAMPLES.slice();
function renderFiles(sel) {
  files.innerHTML = list.map((f, i) =>
    '<button type="button" class="mup-guard__file" role="radio" aria-checked="' + (i === sel) + '" tabindex="' + (i === sel ? 0 : -1) + '" data-i="' + i + '">' +
    '<i>' + esc((extOf(f.name) || '?').slice(0, 4).toUpperCase()) + '</i>' + esc(f.mine ? 'Yours: ' + f.name : f.name) + '</button>').join('');
}
function select(i, focus) {
  $$('.mup-guard__file', files).forEach((b, k) => { b.setAttribute('aria-checked', String(k === i)); b.tabIndex = k === i ? 0 : -1; });
  const b = $$('.mup-guard__file', files)[i];
  if (focus) b.focus();
  b.scrollIntoView({ block: 'nearest', inline: 'nearest', behavior: RM.matches ? 'auto' : 'smooth' });
  inspect(list[i]);
}
files.addEventListener('click', (e) => { const b = e.target.closest('.mup-guard__file'); if (b) select(+b.dataset.i, false); });
files.addEventListener('keydown', (e) => {
  const bs = $$('.mup-guard__file', files), k = bs.indexOf(document.activeElement);
  if (k < 0) return;
  let n = -1;
  if (e.key === 'ArrowRight' || e.key === 'ArrowDown') n = (k + 1) % bs.length;
  else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') n = (k - 1 + bs.length) % bs.length;
  else if (e.key === 'Home') n = 0;
  else if (e.key === 'End') n = bs.length - 1;
  if (n < 0) return;
  e.preventDefault();
  select(n, true);
});

/* ---------- one inspection: read, match, check, stamp ---------- */
const OK = '<svg class="mup-guard__i" viewBox="0 0 24 24"><path d="m6.5 12.5 3.75 3.75 7.25-8"/></svg>';
const NO = '<svg class="mup-guard__i" viewBox="0 0 24 24"><path d="M8 8l8 8M16 8l-8 8"/></svg>';
function inspect(f) {
  timers.forEach(clearTimeout); timers = [];
  cancelAnimationFrame(upRaf);
  const my = ++run;
  cur = f;
  ['data-read', 'data-match', 'data-checks', 'data-done', 'data-up'].forEach((a) => root.removeAttribute(a));
  root.dataset.verdict = '';
  const { sig, out } = inspectFile(f);
  const fails = out.filter((c) => !c.ok);
  const pass = !fails.length;
  fname.textContent = f.name; fname.title = f.name;
  fsize.textContent = fmt(f.size);
  kindEl.textContent = sig ? sig.label : 'Unknown contents';
  const m = sig ? sig.sig.map((_, k) => sig.at + k) : [];
  const bad = sig && !ALLOW[sig.id];
  let h = '';
  for (let r = 0; r < 2; r++) {
    h += '<span class="mup-guard__off">' + (r * 8).toString(16).padStart(4, '0').toUpperCase() + '</span>';
    let asc = '';
    for (let c = 0; c < 8; c++) {
      const i = r * 8 + c, v = f.bytes[i], mi = m.indexOf(i);
      h += '<b style="--i:' + i + (mi >= 0 ? ';--m:' + mi : '') + '"' + (mi >= 0 ? ' data-m' + (bad ? ' data-bad' : '') : '') + '>' + (v == null ? '··' : v.toString(16).padStart(2, '0').toUpperCase()) + '</b>';
      asc += v == null ? ' ' : v >= 32 && v < 127 ? String.fromCharCode(v) : '·';
    }
    h += '<span class="mup-guard__asc">' + esc(asc) + '</span>';
  }
  hex.innerHTML = h;
  sigEl.toggleAttribute('data-bad', !!bad || !sig);
  sigEl.innerHTML = sig ? 'Signature <code>' + esc(sig.show) + '</code> at byte ' + sig.at + ' · <b>' + sig.label + '</b>' : 'No known signature in the first ' + f.bytes.length + ' bytes';
  checksEl.innerHTML = out.map((c, i) => '<li class="mup-guard__check" data-ok="' + c.ok + '" style="--i:' + i + '"><span aria-hidden="true">' + (c.ok ? OK : NO) + '</span><p>' + esc(c.t) + '<small>' + esc(c.d) + '</small></p></li>').join('');
  stamp.textContent = pass ? 'Cleared' : 'Blocked';
  verdictEl.innerHTML = 'Inspecting ' + esc(f.name) + '…';
  goBtn.disabled = true;
  goLbl.textContent = 'Upload';
  prog.style.setProperty('--mup-guard-p', 0);
  const fast = RM.matches;
  later(fast ? 10 : 30, () => root.setAttribute('data-read', ''));
  later(fast ? 20 : 640, () => root.setAttribute('data-match', ''));
  later(fast ? 30 : 980, () => root.setAttribute('data-checks', ''));
  later(fast ? 40 : 980 + out.length * 120 + 380, () => {
    if (my !== run) return;
    root.dataset.verdict = pass ? 'pass' : 'block';
    root.setAttribute('data-done', '');
    verdictEl.innerHTML = pass ? 'Cleared for upload<small>' + esc((sig ? sig.label : 'File') + ' · ' + fmt(f.size)) + '</small>'
      : 'Blocked: ' + esc(fails[0].s) + '<small>' + fails.length + ' of ' + out.length + ' checks failed · not sent</small>';
    goBtn.disabled = false;
    goLbl.textContent = pass ? 'Upload' : 'Try another';
    say(f.name + ': ' + (pass ? 'cleared for upload. ' : 'blocked, ' + fails[0].s + '. ') + out.map((c) => (c.ok ? 'Pass: ' : 'Fail: ') + c.t).join('. ') + '.');
  });
}

goBtn.addEventListener('click', () => {
  if (root.dataset.verdict === 'block') { input.click(); return; }
  if (root.dataset.verdict !== 'pass' || root.hasAttribute('data-up')) return;
  const f = cur, t0 = performance.now(), dur = RM.matches ? 300 : 900 + Math.min(1600, f.size / 2500);
  root.setAttribute('data-up', '');
  goBtn.disabled = true;
  const step = (t) => {
    if (!root.isConnected) return;
    if (cur !== f) return;
    const p = Math.min(1, (t - t0) / dur);
    prog.style.setProperty('--mup-guard-p', p.toFixed(3));
    goLbl.textContent = Math.floor(p * 100) + '%';
    if (p < 1) { upRaf = requestAnimationFrame(step); return; }
    goLbl.textContent = 'Attached';
    verdictEl.innerHTML = 'Attached to load HF-20931<small>' + esc(f.name) + ' · ' + fmt(f.size) + '</small>';
    say(f.name + ' attached to load HF-20931.');
  };
  upRaf = requestAnimationFrame(step);
});

/* ---------- your own file: only the first 16 bytes are read, locally ---------- */
$('[data-act="choose"]').addEventListener('click', () => input.click());
input.addEventListener('change', async () => {
  const file = input.files[0];
  input.value = '';
  if (!file) return;
  let bytes = [];
  try { bytes = [...new Uint8Array(await file.slice(0, 16).arrayBuffer())]; } catch (e) { bytes = []; }
  if (!root.isConnected) return;
  list = SAMPLES.concat([{ name: file.name, size: file.size, bytes, mine: true }]);
  renderFiles(list.length - 1);
  select(list.length - 1, true);
});

renderFiles(0);
inspect(list[0]);
